package app.anemia.core

/**
 * Checks for the ported `:core` slice. Run with `Scripts/test-core.sh`.
 *
 * These mirror the assertions in `Tests/LoaderCoreTests/AWGTests.swift` on
 * purpose: the Swift behaviour is the contract, and where the two disagree the
 * port is wrong (or the Swift test was, which is rarer).
 */

/**
 * The UAPI script compared with what the Swift code produces.
 *
 * The `.uapi` files are generated by `LoaderTool awg-uapi` — the same
 * `AmneziaWGConfigBuilder` the Mac and iOS apps call — so this is not the port
 * checking itself against itself: a key renamed, reordered, or hex-encoded
 * differently on one side fails here. Regenerate with
 * `Scripts/golden-awg.sh` after changing the Swift builder.
 */
/**
 * Вычитание сетей для `VpnService`. Контракта в Swift тут нет — исключающих
 * маршрутов на iOS не считают, они там отдаются системе как есть. Поэтому
 * проверяются свойства: куски не пересекаются с тем, что вычли, и по размеру
 * закрывают ровно «разрешённое минус вычтенное».
 */
private fun routeArithmetic() {
    check("вычитание сетей для маршрутов") {
        val cases = listOf(
            listOf("0.0.0.0/0") to listOf("10.0.0.0/8"),
            listOf("0.0.0.0/0") to listOf("0.0.0.0/1"),
            // Разрешённые сети берём непересекающимися: сумма размеров равна
            // «allowed минус excluded» только тогда, когда allowed не дублируют
            // друг друга (пересечения `included` не склеивает — Android это
            // безразлично, а свойство размера уже не работает).
            listOf("0.0.0.0/1", "192.168.0.0/16") to listOf("192.168.1.1/32"),
            listOf("::/0") to listOf("2001:db8::/32"),
            listOf("0.0.0.0/0") to listOf("203.0.113.0/24", "198.51.100.0/24"),
            listOf("10.0.0.0/8") to listOf("0.0.0.0/0"),
        )
        for ((allowed, excluded) in cases) {
            val pieces = Routes.included(allowed, excluded)
            val label = "$allowed − $excluded: "
            val parsed = pieces.mapNotNull { Routes.parse(it) }
            expect(parsed.size, pieces.size, "куски разобрались обратно: $label")
            for (piece in parsed) {
                for (gap in excluded.mapNotNull(Routes::parse)) {
                    expectTrue(!piece.contains(gap) && !gap.contains(piece),
                        "$piece пересекается с вычтенной $gap: $label")
                }
            }
            // Размер: сумма 2^(width-bits) по кускам равна размеру allowed
            // минус та часть excluded, что внутри allowed.
            fun size(prefixes: List<Routes.Prefix>) =
                prefixes.sumOf { java.math.BigInteger.ONE.shiftLeft(it.width - it.bits).toDouble() }
            // Пересечение двух сетей: та, что меньше, и есть пересечение; если
            // одна не содержит другую — нуль. Вычитаемые сети в кейсах между
            // собой не пересекаются, иначе сумма их размеров завысила бы «хотелку».
            fun intersection(allowed: Routes.Prefix, gap: Routes.Prefix): Double = when {
                allowed.ipv6 != gap.ipv6 -> 0.0
                allowed.contains(gap) -> Math.scalb(1.0, allowed.width - gap.bits)
                gap.contains(allowed) -> Math.scalb(1.0, allowed.width - allowed.bits)
                else -> 0.0
            }
            val allowedParsed = allowed.mapNotNull(Routes::parse)
            val gapParsed = excluded.mapNotNull(Routes::parse)
            val wanted = size(allowedParsed) - allowedParsed.sumOf { keep ->
                gapParsed.sumOf { intersection(keep, it) }
            }
            expectTrue(Math.abs(size(parsed) - wanted) < 1.0, "размер не сходится: $label")
            // Каждый вычитаемый/network может добавить не больше width+1
            // кусков (деление пополам на каждом уровне).
            val levels = parsed.firstOrNull()?.width ?: 32
            expectTrue(pieces.size <= allowed.size + excluded.size * (levels + 1),
                "кусков подозрительно много: $label")
        }
        // Ручной кейс: /0 без 10.0.0.0/8. Деление идёт по одному биту, и на
        // пути к /8 остаётся по соседу с каждой развилки: 128/1 (весь старший
        // бит — 10.x лежит в младшем), затем 64/2, 32/3, 16/4, 0/5, и внутри
        // 8/5 — 12/6, внутри 8/6 — 8/7, внутри 10/7 — 12/8.
        expect(
            Routes.included(listOf("0.0.0.0/0"), listOf("10.0.0.0/8")),
            listOf("128.0.0.0/1", "64.0.0.0/2", "32.0.0.0/3", "16.0.0.0/4",
                "0.0.0.0/5", "12.0.0.0/6", "8.0.0.0/7", "11.0.0.0/8"),
            "0.0.0.0/0 минус 10.0.0.0/8: ",
        )
    }
}

private fun goldenAwg(dir: String?) {
    check("UAPI совпадает с эталоном из Swift (LoaderTool)") {
        val folder = java.io.File(dir ?: "core/src/test/resources/awg")
        val confs = folder.listFiles { file -> file.name.endsWith(".conf") }?.sortedBy { it.name }
            ?: throw AssertionError("нет каталога с эталонами: ${folder.absolutePath}")
        expectTrue(confs.isNotEmpty(), "каталог ${folder.absolutePath} пуст")
        for (conf in confs) {
            val expected = java.io.File(conf.parentFile,
                conf.name.removeSuffix(".conf") + ".uapi")
            if (!expected.exists()) throw AssertionError("нет эталона ${expected.name}")
            val actual = AmneziaWg.uapiScript(WireGuardConf.parse(conf.readText()))
            expect(actual.trim(), expected.readText().trim(), "${conf.name}: ")
        }
        // Ни один парный эталон не должен висеть без конфига: glob по `.conf`
        // молча перестал бы его читать, и проверка весела бы ровно на число
        // потерянных файлов меньше. `links.uapi` — агрегат, у него своего
        // `.conf` нет по построению.
        val names = confs.map { it.name.removeSuffix(".conf") }.toSet()
        val aggregates = setOf("links.uapi")
        val orphans = (folder.listFiles { f ->
            (f.name.endsWith(".uapi") || f.name.endsWith(".problems.txt")) && f.name !in aggregates
        } ?: emptyArray()).mapNotNull { f ->
            when {
                f.name.endsWith(".uapi") -> f.name.removeSuffix(".uapi")
                else -> f.name.removeSuffix(".problems.txt")
            }
        }.filter { it !in names }.sorted()
        expect(orphans, emptyList(), "эталоны без конфига: ")

        // И то же для сервера из подписки: `ProxyServer`, а не разобранный
        // conf. Именно этим путём живое приложение поднимает AmneziaWG, и
        // до этой строки порт вообще не умел собирать UAPI по ссылке.
        val links = java.io.File(folder, "links.txt")
        val linksGolden = java.io.File(folder, "links.uapi")
        if (!links.exists() || !linksGolden.exists()) {
            throw AssertionError("нет ${links.name}/${linksGolden.name}: перегенерируй Scripts/golden-awg.sh")
        }
        val rows = links.readLines().filter { it.isNotEmpty() }
        // Блоки `links.uapi` — голый текст скрипта (в нём `key=value`, а не
        // `key\tvalue`), поэтому читаются своим делителем, не parseBlocks.
        val blocks = LinkedHashMap<String, StringBuilder>()
        var block: String? = null
        for (line in linksGolden.readLines()) {
            if (line.startsWith("=== ")) {
                block = line.removePrefix("=== ")
                blocks[block] = StringBuilder()
            } else if (block != null) blocks.getValue(block).appendLine(line)
        }
        expect(rows.size, blocks.size, "число ссылок: ")
        var refused = 0
        for (row in rows) {
            val label = row.substringBefore('\t')
            val link = row.substringAfter('\t')
            val want = blocks[label] ?: throw AssertionError("нет эталона для $label")
            val actual = try {
                AmneziaWg.uapiScript(ShareLinkParser.parse(link))
            } catch (error: ProxyParseException) {
                refused += 1
                "error: ${parseErrorText(error)}"
            } catch (error: AwgConfigException) {
                refused += 1
                "error: ${parseErrorText(error)}"
            }
            expect(actual.trim(), want.toString().trim(), "$label: ")
        }
        println("   · ссылок сверено: ${rows.size}, из них движок их отвергает: $refused")
    }
}

/**
 * The country a server name reveals, compared with the Swift `Country` —
 * the same code that titles the Dynamic Island, the map and the server
 * groups. Code, flag and "place" are pure logic and must match exactly;
 * the spelled-out country name comes from the system's CLDR, whose vintage
 * differs between Apple and the JVM, so mismatches there are printed rather
 * than failed — visible, not silently forgiven.
 */
private fun goldenCountry(dir: String?) {
    check("Country совпадает с эталоном из Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/country")
        val names = java.io.File(folder, "names.txt")
        val golden = java.io.File(folder, "names.tsv")
        if (!names.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-country.sh")
        }
        val inputs = names.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число строк: ")
        val cldr = mutableListOf<String>()
        for ((index, line) in expected.withIndex()) {
            val (code, flag, place, name) = line.split('\t')
            val input = inputs[index]
            val actual = code.takeIf { it.isNotEmpty() }.let { c ->
                Triple(
                    Country.code(input) ?: "",
                    c?.let { Country.flag(it) } ?: "",
                    Country.place(input),
                )
            }
            expect(actual.first, code, "код «$input»: ")
            expect(actual.second, flag, "флаг «$input»: ")
            expect(actual.third, place, "место «$input»: ")
            if (code.isNotEmpty()) {
                val ours = Country.name(code)
                if (ours != name) cldr.add("$code: Apple «$name» / JVM «$ours»")
            }
        }
        if (cldr.isNotEmpty()) println("   · имена стран расходятся с CLDR Apple: ${cldr.joinToString("; ")}")

        // codes.txt — не имена серверов, а «коды страны» как их видит
        // приложение: поле `loc` из ответа leak-сервиса, три буквы, цифры,
        // кириллица. Здесь проверяется решение «нашёл название / отдал код»,
        // а не содержимое CLDR.
        val codes = java.io.File(folder, "codes.txt")
        val codesGolden = java.io.File(folder, "codes.tsv")
        if (!codes.exists() || !codesGolden.exists()) {
            throw AssertionError("нет фикстур ${codes.name}/${codesGolden.name}: перегенерируй Scripts/golden-country.sh")
        }
        val codeInputs = codes.readLines().filter { it.isNotEmpty() }
        val codeExpected = codesGolden.readLines().filter { it.isNotEmpty() }
        expect(codeInputs.size, codeExpected.size, "число кодов: ")
        val alias = mutableListOf<String>()
        for ((index, line) in codeExpected.withIndex()) {
            val fields = line.split('\t')
            expectTrue(fields.size >= 3, "эталонной строке не хватает колонок: «$line»")
            val code = codeInputs[index]
            expect(code, fields[0], "код фикстуры разошёлся с эталоном: ")
            expect(Country.flag(code), fields[1], "флаг для «$code»: ")
            val name = Country.name(code)
            when {
                // Apple не нашёл названия и вернул сам код — порт обязан
                // сделать то же (и не бросить на «1» или «RUS»).
                fields[2] == code -> expect(name, code, "ненайденное название для «$code»: ")
                name != fields[2] -> alias.add("$code: Apple «${fields[2]}» / JVM «$name»")
            }
        }
        if (alias.isNotEmpty()) println("   · имена не покрываются таблицей алиасов JVM: ${alias.joinToString("; ")}")
    }
}

/**
 * What the validator says about each fixture conf, compared line by line with
 * the messages the Swift builder prints (`golden-awg-problems.sh`). The text
 * is part of the contract: a reworded message on one platform fails here.
 */
private fun goldenProblems(dir: String?) {
    check("проблемы конфига — те же строки, что у Swift-валидатора") {
        val folder = java.io.File(dir ?: "core/src/test/resources/awg")
        val confs = folder.listFiles { file -> file.name.endsWith(".conf") }?.sortedBy { it.name }
            ?: throw AssertionError("нет фикстур в ${folder.absolutePath}")
        for (conf in confs) {
            val report = java.io.File(conf.parentFile, conf.name.removeSuffix(".conf") + ".problems.txt")
            if (!report.exists()) throw AssertionError("нет эталона ${report.name}")
            val server = WireGuardConf.parse(conf.readText())
            val actual = (AwgValidate.validate(server).map { "problem: $it" } +
                AwgValidate.warnings(server).map { "warning: $it" })
            expect(actual, report.readLines().filter { it.isNotEmpty() }, "${conf.name}: ")
        }
    }
}

/**
 * Share links, compared field by field with what the Swift parser makes of
 * the same corpus (`Scripts/golden-links.sh`). Every scheme Swift accepts is
 * ported, so a link that Kotlin can't read at all now shows up as a field
 * mismatch rather than as a skip.
 */
private fun goldenLinks(dir: String?) {
    check("разбор ссылок совпадает с Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/links")
        val corpus = java.io.File(folder, "corpus.txt")
        val golden = java.io.File(folder, "corpus.golden.txt")
        if (!corpus.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-links.sh")
        }
        val expected = parseBlocks(golden.readText())
        val links = corpus.readLines().filter { it.isNotBlank() }
        expect(links.size, expected.size, "число ссылок: ")
        var errors = 0
        for (link in links) {
            // The tool trims each line before parsing it, so its block header —
            // and therefore the golden key — is the trimmed link.
            val want = expected[trimSpaceLike(link)]
                ?: throw AssertionError("нет эталона для «$link»")
            val got = try {
                ShareLinkParser.parse(link).let { dump(it) }
            } catch (error: ProxyParseException) {
                errors += 1
                mapOf("error" to error.describe())
            }
            expect(got, want, "«$link»: ")
        }
        println("   · сверено ссылок: ${links.size}, из них с ожидаемой ошибкой разбора: $errors")
        if (links.isEmpty()) throw AssertionError("корпус пуст — порт не покрыт")
    }
}

/** The Swift dump of one server, in the same keys the tool prints. */
private fun dump(server: ProxyServer): Map<String, String> = mapOf(
    "name" to server.name,
    "proto" to server.proto.raw,
    "address" to server.address,
    "port" to server.port.toString(),
    "credential" to server.credential,
    "method" to (server.method ?: ""),
    "alterId" to server.alterId.toString(),
    "vmessCipher" to (server.vmessCipher ?: ""),
    "network" to server.network.raw,
    "security" to server.security.raw,
    "sni" to (server.sni ?: ""),
    "alpn" to server.alpn.joinToString(","),
    "fingerprint" to (server.fingerprint ?: ""),
    "allowInsecure" to server.allowInsecure.toString(),
    "realityPublicKey" to (server.realityPublicKey ?: ""),
    "realityShortId" to (server.realityShortId ?: ""),
    "realitySpiderX" to (server.realitySpiderX ?: ""),
    "flow" to (server.flow ?: ""),
    "path" to (server.path ?: ""),
    "host" to (server.host ?: ""),
    "headerType" to (server.headerType ?: ""),
    "grpcMultiMode" to (server.grpcMultiMode?.toString() ?: ""),
    "xhttpMode" to (server.xhttpMode ?: ""),
    "xhttpExtra" to (server.xhttpExtra ?: ""),
    "vlessEncryption" to (server.vlessEncryption ?: ""),
    "awgVersion" to if (server.proto.isWireGuardFamily) AwgVersion.detect(server.awg).label else "",
    "wgAddresses" to (server.userData?.get("wgAddress") ?: ""),
    "wgPeer" to (server.wgProfile?.peerPublicKey ?: ""),
    "wgPreshared" to (server.wgProfile?.presharedKey ?: ""),
    "wgAllowedIPs" to (server.wgProfile?.allowedIPs?.joinToString(", ") ?: ""),
    "wgDNS" to (server.wgProfile?.dns?.joinToString(", ") ?: ""),
    "wgMTU" to (server.wgProfile?.mtu?.toString() ?: ""),
    "wgKeepAlive" to (server.wgProfile?.keepAlive?.toString() ?: ""),
    "userData" to server.userData.orEmpty().entries.sortedBy { it.key }.joinToString(";") { "${it.key}=${it.value}" },
)

/** `=== <link>` blocks of the golden file into link → fields. */
private fun parseBlocks(text: String): Map<String, Map<String, String>> {
    val result = mutableMapOf<String, Map<String, String>>()
    var link: String? = null
    var fields = mutableMapOf<String, String>()
    for (line in text.lineSequence()) {
        if (line.startsWith("=== ")) {
            link?.let { result[it] = fields.toMap() }
            link = line.removePrefix("=== ")
            fields = mutableMapOf()
        } else if (line.contains('\t') && link != null) {
            val index = line.indexOf('\t')
            fields[line.substring(0, index)] = line.substring(index + 1)
        }
    }
    link?.let { result[it] = fields.toMap() }
    return result
}

/**
 * The flexible base64 decoder the port reimplements from scratch — vmess JSON,
 * legacy `ss://` payloads and `amnezia://` conf blobs all come through it. The
 * table is mostly junk on purpose: Foundation stops at padding, drops surplus
 * bits and rejects junk after padding, and none of that is visible in a
 * well-formed link. Regenerate with `Scripts/golden-base64.sh`.
 */
private fun goldenBase64(dir: String?) {
    check("гибкий base64 совпадает с Foundation") {
        val folder = java.io.File(dir ?: "core/src/test/resources/base64")
        val cases = java.io.File(folder, "cases.txt")
        val golden = java.io.File(folder, "cases.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-base64.sh")
        }
        val lines = golden.readLines().filter { it.isNotEmpty() }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        expect(lines.size, inputs.size, "число случаев: ")
        var empty = 0
        for ((index, input) in inputs.withIndex()) {
            val line = lines[index]
            val key = line.substringBefore('\t', "")
            expect(key, input, "случай №${index + 1}: ")
            val want = line.substringAfter('\t', "")
            val bytes = Base64.decodeFlexible(input)
            val got = when {
                bytes == null -> "nil"
                bytes.isEmpty() -> { empty += 1; "" }
                else -> bytes.joinToString("") { "%02x".format(it.toInt() and 0xFF) }
            }
            expect(got, want, "«$input»: ")
        }
        println("   · случаев: ${inputs.size}, пустых декодов: $empty")
    }
}

/**
 * Which characters Foundation strips as `.whitespaces` /
 * `.whitespacesAndNewlines`, scalar by scalar (`base64/trim-sets.tsv`) — the
 * two sets the port's `trimFoundationSpaces` and `trimSpaceLike` reimplement.
 * A golden of parsed *values* cannot pin these on every runtime: `Char.isWhitespace`
 * counts NBSP as space on this build's JVM and not on Android's libcore, so
 * `trim()` would coincidentally match here and diverge there. Membership is
 * compared directly instead, so the set itself is the contract.
 */
private fun goldenTrimSets(dir: String?) {
    check("наборы пробелов совпадают с Foundation") {
        val folder = java.io.File(dir ?: "core/src/test/resources/base64")
        val table = java.io.File(folder, "trim-sets.tsv")
        if (!table.exists()) {
            throw AssertionError("нет ${table.name}: перегенерируй Scripts/golden-base64.sh")
        }
        val rows = table.readLines().filter { it.isNotEmpty() }
        // Набор, подобранный вручную, может тихо усохнуть до нескольких строк.
        // Ниже — кодовые точки, на которых два набора Foundation расходятся с
        // `Char.isWhitespace`, и они обязаны присутствовать всегда.
        val required = listOf("0009", "000A", "000B", "000C", "000D", "001C", "001F",
            "0020", "0085", "00A0", "1680", "2000", "200B", "2028", "2029", "202F",
            "205F", "3000")
        val present = rows.map { it.substringBefore('\t') }.toSet()
        expect(required.filter { it !in present }, emptyList(), "нет строк таблицы для U+")
        expectTrue(rows.size >= required.size, "таблица пробелов короче обязательного набора")
        for (row in rows) {
            val (hex, spaces, spacesAndNewlines) = row.split('\t')
            val ch = hex.toInt(16).toChar()
            val shown = "U+$hex"
            val wantSpaces = spaces == "Y"
            val wantSpacesAndNewlines = spacesAndNewlines == "Y"
            expect(isFoundationSpace(ch), wantSpaces, "$shown в .whitespaces: ")
            expect(isSpaceLike(ch), wantSpacesAndNewlines, "$shown в .whitespacesAndNewlines: ")
            // И сами trim'ы обязаны слушаться набора: с краёв снимается, внутри
            // слова остаётся (иначе «пробел» в середине pin'а стал бы хексом).
            expect(trimFoundationSpaces("$ch+$ch"), if (wantSpaces) "+" else "$ch+$ch", "$shown через trimFoundationSpaces: ")
            expect(trimSpaceLike("$ch+$ch"), if (wantSpacesAndNewlines) "+" else "$ch+$ch", "$shown через trimSpaceLike: ")
        }
        // Справочная строка, почему наборы заданы руками: `Char.isWhitespace`
        // считает NBSP пробелом на этой JVM и не считает на Android'ом
        // (libcore держится документации Java), то есть `trim()` совпал бы с
        // Foundation здесь и разошёлся там.
        val nbsp = '\u00A0'
        println("   · NBSP: Char.isWhitespace=${nbsp.isWhitespace()} здесь, набор Foundation — ${isSpaceLike(nbsp)}; " +
            "на Android первый false, поэтому сверяем членство, а не trim()")
    }
}

/**
 * The engine config, compared with what the Swift builder produces for the same
 * server in the packet-tunnel shape (`Scripts/golden-xray.sh`). JSON is
 * canonicalised before the diff: Foundation's writer does not order nested keys
 * reproducibly, so a plain text compare would report moves as changes. Refusals
 * count too — the message a user reads is part of the contract.
 */
private fun goldenXray(dir: String?) {
    check("конфиг движка совпадает с Swift (emit-tun)") {
        val folder = java.io.File(dir ?: "core/src/test/resources/xray")
        val cases = java.io.File(folder, "cases.tsv")
        if (!cases.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-xray.sh")
        }
        val rows = cases.readLines().filter { it.isNotBlank() && !it.startsWith("#") }
        var configs = 0
        var refusals = 0
        for (row in rows) {
            val parts = row.split('\t')
            val id = parts[0]
            val link = parts[1]
            val flags = if (parts.size > 2) parts[2].trim().split(' ').filter { it.isNotEmpty() } else emptyList()
            val anti = when {
                flags.contains("--no-anti") -> AntiCensorshipOptions.off
                flags.indexOf("--anti") >= 0 -> {
                    // Маскирование «как из панели»: тот же снисходительный
                    // декодер, что читает state.json. Нужен объект, а не числовой
                    // мусор, иначе кейс молча проверял бы другой профиль.
                    val raw = flags[flags.indexOf("--anti") + 1]
                    if (Json.parse(raw) !is Map<*, *>) throw AssertionError("--anti ждёт объект: $raw")
                    StateCodec.state("{\"anti\":" + raw + "}").anti
                }
                else -> flags.indexOf("--profile").takeIf { it >= 0 && it + 1 < flags.size }
                    ?.let { MaskingProfile.of(flags[it + 1])!!.options }
                    ?: AntiCensorshipOptions.recommended
            }
            var config: String? = null
            var refusal: String? = null
            try {
                config = xrayTunBuilder(flags).makeConfigString(ShareLinkParser.parse(link), anti)
            } catch (error: XrayConfigException) {
                refusal = error.message ?: ""
            }
            val json = java.io.File(folder, "$id.json")
            val err = java.io.File(folder, "$id.err")
            if (json.exists()) {
                if (refusal != null) throw AssertionError("$id: Kotlin отказался — «$refusal», а ждали конфиг")
                expect(canonical(Json.parse(json.readText())),
                       canonical(Json.parse(config!!)), "$id: ")
                configs += 1
            } else if (err.exists()) {
                // The tool prints "error: <description>"; the description is it.
                expect(refusal, err.readText().trim().removePrefix("error: "), "$id (отказ): ")
                refusals += 1
            } else {
                throw AssertionError("$id: нет ни эталона конфига, ни эталона отказа")
            }
        }
        println("   · конфигов сверено: $configs, отказов: $refusals")
        if (configs == 0 || refusals == 0) throw AssertionError("нужны и конфиги, и отказы")
        // И наоборот: лишний .json/.err в каталоге — это кейс, который перестали
        // генерировать. Сверка ходит по cases.tsv, так что сама бы её не заметила.
        val wanted = rows.map { it.split('\t')[0] }.toSet()
        val orphans = (folder.listFiles { f -> f.name.endsWith(".json") || f.name.endsWith(".err") }
            ?: emptyArray()).map { it.name.substringBeforeLast('.') }
            .filter { it !in wanted }.sorted()
        expect(orphans, emptyList(), "эталоны конфига без кейса в cases.tsv: ")
    }
}

/** The builder wired exactly as `LoaderTool emit-tun` wires it. */
private fun xrayTunBuilder(flags: List<String>): XrayConfigBuilder {
    val builder = XrayConfigBuilder(apiPort = null, bufferSizeKB = 4)
    builder.mtu = flags.indexOf("--mtu").takeIf { it >= 0 && it + 1 < flags.size }
        ?.let { flags[it + 1].toIntOrNull() } ?: 1500
    builder.collectsStats = true
    builder.dnsQueryStrategy = "UseIPv4"
    builder.bypassResolver = "77.88.8.8"
    flags.indexOf("--log").takeIf { it >= 0 && it + 1 < flags.size }?.let { builder.logFile = flags[it + 1] }
    flags.indexOf("--bypass").takeIf { it >= 0 && it + 1 < flags.size }?.let {
        builder.bypass = SplitTunnelParser.parse(text = flags[it + 1]).entries
    }
    if (flags.contains("--adblock")) {
        builder.remoteDNS = AdBlockDns.remoteDNS
        builder.dnsHosts[AdBlockDns.dohHost] = AdBlockDns.servers[0]
        builder.bypassResolver = AdBlockDns.servers[0]
    }
    return builder
}

/** Order-insensitive, type-sensitive rendering of one parsed JSON document. */
private fun canonical(value: Any?): Any? = when (value) {
    is Map<*, *> -> value.entries
        .associate { it.key.toString() to canonical(it.value) }
        .toSortedMap()
    is List<*> -> value.map { canonical(it) }
    else -> value
}

/**
 * Документ трафика. `servers` — словарь с UUID-ключами, и Foundation пишет его
 * плоским массивом «ключ, значение, …» в порядке словаря, то есть каждый запуск
 * своим порядком: пары разворачиваются в сортированный словарь, иначе сверка
 * была бы проверкой порядка, а не содержимого.
 */
private fun canonicalTraffic(value: Any?): Any? = when (value) {
    is Map<*, *> -> value.entries.associate { (key, item) ->
        val name = key.toString()
        name to if (name == "servers" && item is List<*>) {
            if (item.size % 2 != 0) {
                throw AssertionError("плоский массив `servers` непарной длины ${item.size}")
            }
            item.chunked(2).associate { pair ->
                pair[0].toString() to canonicalTraffic(pair[1])
            }.toSortedMap()
        } else canonicalTraffic(item)
    }.toSortedMap()
    is List<*> -> value.map { canonicalTraffic(it) }
    else -> value
}

/**
 * Правила раздельного туннелирования: нормализация каждой строки и причина
 * каждого отказа — против вывода Swift-парсера (`Scripts/golden-bypass.sh`).
 * Здесь проверяется то, чего корпус ссылок не касается:canonical-форма CIDR,
 * Punycode для кириллических доменов и запрещённые диапазоны.
 */
private fun goldenBypass(dir: String?) {
    check("правила обхода VPN совпадают с Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/bypass")
        val lines = java.io.File(folder, "lines.txt")
        val golden = java.io.File(folder, "lines.golden.txt")
        if (!lines.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-bypass.sh")
        }
        // Пустая строка в конце фикстуры — не кейс: `LoaderTool split-tunnel`
        // её пропускает, и сверка обязана пропускать.
        val inputs = lines.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число строк: ")
        var entries = 0
        var rejections = 0
        for ((index, input) in inputs.withIndex()) {
            if (input.isEmpty()) continue
            val result = SplitTunnelParser.parse(text = input)
            val described = result.entries.joinToString("") { entry ->
                val kind = when (entry) {
                    is BypassEntry.IPv4 -> "ipv4"
                    is BypassEntry.IPv6 -> "ipv6"
                    is BypassEntry.Domain -> "domain"
                }
                "${entry.value} [$kind(\"${entry.value}\")] "
            } + result.rejected.joinToString("; ") { "нет: ${it.reason}" }
            val parts = expected[index].split('\t')
            expect(parts.size, 2, "формат эталона «$input»: ")
            expect(parts[0], input, "строка эталона: ")
            expect(described, parts[1], "«$input»: ")
            entries += result.entries.size
            rejections += result.rejected.size
        }
        println("   · правил: $entries, отвергнуто строк: $rejections")
        if (entries == 0 || rejections == 0) throw AssertionError("нужны и принятые правила, и отказы")
    }
}

/**
 * Подписка: как Swift разбирает тело (payloads.txt) и заголовки панели
 * (headers.txt). Тело — это то, что панель отдаёт по HTTP-ссылке, и оно
 * приходит и base64-блобом, и списком ссылок, и с CRLF; заголовки — единствен-
 * ный источник сведений о трафике и сроке, а арифметика в нём бывает за
 * пределами Int64. Регенерация: `Scripts/golden-sub.sh`.
 */
private fun goldenSub(dir: String?) {
    check("подписка совпадает с Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/sub")
        val payloads = java.io.File(folder, "payloads.txt")
        val payloadGolden = java.io.File(folder, "payloads.golden.txt")
        val headers = java.io.File(folder, "headers.txt")
        val headerGolden = java.io.File(folder, "headers.golden.txt")
        if (!payloads.exists() || !payloadGolden.exists() || !headers.exists() || !headerGolden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-sub.sh")
        }

        var servers = 0
        var failures = 0
        val actual = StringBuilder()
        for (rawLine in payloads.readLines().filter { it.isNotEmpty() }) {
            actual.append("=== ").append(rawLine).append('\n')
            val result = SubscriptionParser.parse(unescapeFixtures(rawLine))
            for (server in result.servers) {
                actual.append("server\t").append(subDump(server)).append('\n')
            }
            for ((line, error) in result.failures) {
                actual.append("failure\t").append(line).append('\t').append(error).append('\n')
            }
            actual.append("count\t").append(result.servers.size)
                .append(' ').append(result.failures.size).append('\n')
            servers += result.servers.size
            failures += result.failures.size
        }
        compareGolden(actual.toString(), payloadGolden.readText(), "тело подписки")

        val info = StringBuilder()
        var parsed = 0
        for (rawLine in headers.readLines().filter { it.isNotEmpty() }) {
            val parts = rawLine.split('\t')
            if (parts.size < 2) continue
            val map = LinkedHashMap<String, String>()
            for (header in parts.drop(1)) {
                val colon = header.indexOf(':')
                if (colon < 0) continue
                map[header.substring(0, colon)] = header.substring(colon + 1)
            }
            info.append(subInfoDump(parts[0], SubscriptionInfo.parse(map))).append('\n')
            if (SubscriptionInfo.parse(map) != null) parsed += 1
        }
        compareGolden(info.toString(), headerGolden.readText(), "заголовки")
        println("   · серверов из тел: $servers, отказов: $failures, наборов заголовков с информацией: $parsed")
    }
}

/**
 * Grammar of `Double(_ string: String)` — `sub/numbers.tsv` is what Foundation
 * itself answers for each case (hex-encoded, so a vertical tab or a newline can
 * be a case at all), and every answer is compared as IEEE-754 bits: `-0` and
 * `0` differ in one bit, and `strtod` keeps that difference.
 */
private fun goldenNumbers(dir: String?) {
    check("грамматика чисел совпадает с Foundation") {
        val folder = java.io.File(dir ?: "core/src/test/resources/sub")
        val cases = java.io.File(folder, "numbers.txt")
        val golden = java.io.File(folder, "numbers.tsv")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-sub.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val rows = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, rows.size, "число кейсов: ")
        var nils = 0
        val shown = StringBuilder()
        for ((index, row) in rows.withIndex()) {
            val (hex, wantDouble, wantInt) = row.split('\t')
            expect(hex, inputs[index], "кейс эталона: ")
            val text = hexBytes(hex).toString(Charsets.UTF_8)
            val value = SwiftDouble.parse(text)
            val got = when {
                value == null -> { nils += 1; "nil" }
                value.isNaN() -> "nan"
                value == Double.POSITIVE_INFINITY -> "inf"
                value == Double.NEGATIVE_INFINITY -> "-inf"
                else -> String.format(java.util.Locale.ROOT, "%016x",
                    java.lang.Double.doubleToRawLongBits(value))
            }
            shown.setLength(0)
            for (ch in text) when {
                ch == '\n' -> shown.append("[LF]")
                ch == '\t' -> shown.append("[TAB]")
                ch == '\u000B' -> shown.append("[VT]")
                ch == '\u00A0' -> shown.append("[NBSP]")
                ch.code in 0x0660..0x0669 -> shown.append("[ARABIC-").append(ch.code - 0x0660).append("]")
                else -> shown.append(ch)
            }
            expect(got, wantDouble, "Double(«$shown»): ")
            expect(SwiftInt.parse(text)?.toString() ?: "nil", wantInt, "Int(«$shown»): ")
        }
        println("   · кейсов: ${inputs.size}, отвергнуто: $nils")
    }
}

/** Escape-последовательности фикстуры в настоящие переводы строк — как в `LoaderTool sub`. */
private fun unescapeFixtures(line: String): String {
    val out = StringBuilder(line.length)
    var index = 0
    while (index < line.length) {
        if (line[index] == '\\' && index + 1 < line.length) {
            when (line[index + 1]) {
                'n' -> { out.append('\n'); index += 2; continue }
                'r' -> { out.append('\r'); index += 2; continue }
                't' -> { out.append('\t'); index += 2; continue }
                'v' -> { out.append('\u000B'); index += 2; continue }
                'f' -> { out.append('\u000C'); index += 2; continue }
                else -> {}
            }
        }
        out.append(line[index])
        index += 1
    }
    return out.toString()
}

// Дамп полей сервера для золота подписки — тот же `dump`, что и для золота
// ссылок, и в том же порядке: `LoaderTool sub` печатает все 34 поля, иначе
// половина модели в подписке не сверялась бы.
private fun subDump(server: ProxyServer): String =
    dump(server).entries.sortedBy { it.key }
        .joinToString(" ") { "${it.key}=${it.value}" }

/** The `LoaderTool subinfo` line for one header set, 13 fields. */
private fun subInfoDump(id: String, info: SubscriptionInfo?): String {
    fun number(value: Long?) = value?.toString() ?: "—"
    val title = if (info == null) "nil" else info.title ?: "—"
    val seconds = info?.expires
    val expires = when {
        seconds == null -> "—"
        // Swift печатает expires через Date: Double(Int64.max) уже не влезает в Int64,
        // и там же guard от «overflow» — тот же край повторяем здесь.
        seconds.toDouble() >= Long.MAX_VALUE.toDouble() -> "overflow"
        else -> seconds.toString()
    }
    return listOf(
        id, "title=" + title,
        "up=" + number(info?.uploaded),
        "down=" + number(info?.downloaded),
        "total=" + number(info?.total),
        "used=" + number(info?.used),
        "remaining=" + number(info?.remaining),
        "unlimited=" + (info?.isUnlimited ?: false).toString(),
        "fraction=" + (info?.usedFraction?.let { java.lang.String.format(java.util.Locale.ROOT, "%.4f", it) } ?: "—"),
        "expires=$expires",
        "interval=" + (info?.updateInterval?.let { java.lang.String.format(java.util.Locale.ROOT, "%.0f", it) } ?: "—"),
        "support=" + (info?.supportUrl ?: "—"),
        "web=" + (info?.webPageUrl ?: "—"),
        "announce=" + (info?.announcement ?: "—"),
    ).joinToString("\t")
}

/** Line-by-line compare with a pointer to the first difference. */
private fun compareGolden(actual: String, expected: String, what: String) {
    val got = actual.trimEnd('\n').split('\n')
    val want = expected.trimEnd('\n').split('\n')
    expect(got.size, want.size, "$what: число строк: ")
    for ((index, line) in want.withIndex()) {
        if (got[index] != line) {
            throw AssertionError("$what, строка ${index + 1}:\n     ждали $line\n     получили ${got[index]}")
        }
    }
}

/**
 * Состояние клиента: что Swift читает из `state.json`, что из этого выживает и
 * что он пишет обратно. Кейсы лежат в файлами `state/cases/`, эталон —
 * `Scripts/golden-state.sh`. Здесь проверяется не «ещё один парсер», а цена
 * ошибки в нём: одно отравленное поле не должно уносить весь список серверов,
 * а расхождение схемы — молча съедать записи (страховка `backup`).
 *
 * Рядом пишется `/tmp/anemia-state-kotlin/<case>.json` — то, что Kotlin пишет
 * сам: `Scripts/verify-state.sh` прогоняет эти файлы обратно через Swift-декодер.
 */
private fun goldenState(dir: String?) {
    check("состояние совпадает с Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/state")
        val cases = java.io.File(folder, "cases")
        val golden = java.io.File(folder, "cases.golden.txt")
        if (!cases.isDirectory || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-state.sh")
        }
        val expected = parseBlocks(golden.readText())
        val files = cases.listFiles { file -> file.name.endsWith(".json") }?.sortedBy { it.name }
            ?: throw AssertionError("нет каталога ${cases.absolutePath}")
        expect(files.size, expected.size, "число кейсов: ")

        val written = java.io.File("/tmp/anemia-state-kotlin")
        written.mkdirs()
        val stamp = System.currentTimeMillis()
        var dropped = 0
        var survived = 0
        for (case in files) {
            val name = case.name.removeSuffix(".json")
            val want = expected[name] ?: throw AssertionError("нет эталона для $name")
            val text = case.readText()
            val loaded = StateCodec.load(text)
            val mine = Json.parse(StateCodec.encode(loaded.state))
            for (line in listOf("decode", "loaded")) {
                val reference = want[line] ?: throw AssertionError("$name: нет строки $line в эталоне")
                if (reference == "throw") continue
                expect(canonical(mine), canonical(Json.parse(reference)), "$name ($line): ")
            }
            val backup = want["backup"]?.trim()?.toIntOrNull()
            expect(loaded.needsBackup, backup == 1, "$name: страховка: ")
            // «Сколько страховок остаётся» берётся из эталона: Swift делает
            // четыре чтения испорченного магазина и считает `.bak` — три
            // оставляет prune, чистый кейс даёт ноль. Без этой строки
            // «храним три» было нашим решением, а не перенесённым.
            val sandbox = java.nio.file.Files.createTempDirectory("anemia-prune").toFile()
            val copy = java.io.File(sandbox, "state.json")
            copy.writeText(text)
            var tick = stamp
            repeat(4) { StatePersistence(copy) { tick += 5_000; tick }.load() }
            expect(
                (sandbox.list { _, entry -> entry.endsWith(".bak") } ?: emptyArray()).size,
                want["backups"]?.trim()?.toIntOrNull(), "$name: страховок после четырёх чтений: ",
            )
            sandbox.deleteRecursively()
            if (backup == 1) dropped += 1
            survived += loaded.state.allServers.size
            // Через StatePersistence: тогда verify-state.sh перечитывает
            // Swift'ом тот самый файл, который пишет приложение.
            StatePersistence(java.io.File(written, "${name}.json")).save(loaded.state)
        }
        println("   · кейсов: ${files.size}, с потерянными записями: $dropped, серверов после разбора: $survived")
    }
}

/**
 * Перенос состояния между платформами: `LoaderTool sync` прогоняет кейсы
 * (`sync/cases`) через настоящий Swift-декодер бандлов, пишет обе формы и
 * делает слияние. Здесь сверяется всё: чтение чужого файла и ссылки, отказ на
 * мусоре и на «слишком новом» бандле, побайтово — файловая форма (в бандле нет
 * чисел с плавающей точкой, так что байты обязаны совпасть), и итог слияния.
 * Свою ссылку Kotlin тоже пишет — в `/tmp/anemia-sync-kotlin`, откуда её
 * перечитывает `Scripts/verify-sync.sh`.
 */
private fun goldenSync(dir: String?) {
    check("перенос состояния совпадает с Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/sync")
        val cases = java.io.File(folder, "cases")
        val golden = java.io.File(folder, "cases.golden.txt")
        if (!cases.isDirectory || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-sync.sh")
        }
        val expected = parseBlocks(golden.readText())
        val files = cases.listFiles { file -> file.name.endsWith(".json") }?.sortedBy { it.name }
            ?: throw AssertionError("нет каталога ${cases.absolutePath}")
        expect(files.size, expected.size, "число кейсов: ")

        val written = java.io.File("/tmp/anemia-sync-kotlin")
        written.mkdirs()
        var reads = 0
        var merges = 0
        for (case in files) {
            val name = case.name.removeSuffix(".json")
            val want = expected[name] ?: throw AssertionError("нет эталона для $name")
            val root = Json.parse(case.readText()) as? Map<*, *>
                ?: throw AssertionError("$name: кейс не объект")
            val kind = root["kind"] as? String ?: throw AssertionError("$name: нет kind")
            when (kind) {
                "read" -> {
                    val body = root["body"] as? String ?: throw AssertionError("$name: нет body")
                    val result = runCatching { SyncBundle.decode(body) }
                    val failure = result.exceptionOrNull() as? SyncDecodeException
                    if (failure != null) {
                        expect(failure.describe(), want["error"] ?: "", "$name: ")
                    } else {
                        expect(bundleDump(result.getOrThrow()), want["bundle"] ?: "", "$name: ")
                    }
                    reads += 1
                }
                "file" -> {
                    val bundle = syncCaseBundle(root)
                    val text = bundle.fileData()
                    expect(
                        java.util.Base64.getEncoder().encodeToString(text.toByteArray(Charsets.UTF_8)),
                        want["file-bytes"] ?: "", "$name: байты файла: ",
                    )
                    expect(canonical(Json.parse(text)), canonical(Json.parse(want["file"] ?: "null")),
                           "$name: ")
                    expect(bundleDump(SyncBundle.decode(text)), want["file-read"] ?: "", "$name: обратно: ")
                    java.io.File(written, "${name}.anemia").writeText(text)
                }
                "link" -> {
                    val bundle = syncCaseBundle(root)
                    java.io.File(written, "${name}.txt").writeText(bundle.link())
                    // Два deflate-кодировщика дают разные байты намеренно —
                    // сверяется то, что ссылку читает другая сторона.
                    expect(bundleDump(SyncBundle.fromLink(want["link"] ?: "")), want["link-read"] ?: "",
                           "$name: ссылка Swift'а: ")
                }
                "merge" -> {
                    val bundle = syncCaseBundle(root)
                    val state = StateCodec.load(Json.write(root["state"])).state
                    val (summary, after) = bundle.mergeInto(state, (root["apply"] as? Boolean) ?: true)
                    expect(
                        "added=${summary.addedServers} known=${summary.knownServers}" +
                            " new=${summary.newSubscriptions.size}" +
                            " knownSubs=${summary.knownSubscriptions}" +
                            " settings=${if (summary.settingsApplied) 1 else 0}" +
                            " nothing=${if (summary.addsNothing) 1 else 0}",
                        want["summary"] ?: "", "$name: ",
                    )
                    expect(mergeAfterDump(after), want["after"] ?: "", "$name: ")
                    merges += 1
                }
                else -> throw AssertionError("$name: неизвестный kind $kind")
            }
        }
        println("   · кейсов: ${files.size}, чтений бандла: $reads, слияний: $merges")
    }
}

/** Бандл из кейса: тот же JSON, что Swift декодирует своим `JSONDecoder`. */
private fun syncCaseBundle(case: Map<*, *>): SyncBundle =
    SyncBundle.read(Json.write(case["bundle"]))

/** `LoaderTool sync` печатает бандл так; порядок полей — часть контракта. */
private fun bundleDump(bundle: SyncBundle): String {
    val seconds = bundle.exportedAt
    return listOf(
        "version=${bundle.version}",
        "device=${bundle.device}",
        "at=" + if (seconds >= Long.MAX_VALUE.toDouble() || seconds < Long.MIN_VALUE.toDouble()) "overflow"
        else seconds.toLong().toString(),
        "servers=" + bundle.servers.joinToString(";") { it.identityKey },
        "subs=" + bundle.subscriptions.joinToString(";") { "${it.name}@${it.url}" },
        "settings=" + (bundle.settings?.let { settingsDump(it) } ?: "nil"),
    ).joinToString(" ")
}

private fun settingsDump(settings: SyncBundle.Settings): String {
    fun flag(value: Boolean?) = if (value == null) "-" else if (value) "1" else "0"
    return "masking=" + (settings.maskingProfile?.name ?: "-") +
        " kill=" + flag(settings.killSwitchEnabled) +
        " split=" + (settings.splitTunnel?.let {
            (if (it.enabled) "on" else "off") + ":" + it.entries.joinToString(",")
        } ?: "-") +
        " learned=" + (settings.learnedMasking?.entries?.sortedBy { it.key }
            ?.joinToString(";") { "${it.key}=${it.value}" } ?: "-") +
        " subref=" + flag(settings.subscriptionAutoRefresh) +
        " adblock=" + flag(settings.adBlock) +
        " reconnect=" + flag(settings.autoReconnect) +
        " autoswitch=" + flag(settings.autoSwitch) +
        " adaptive=" + flag(settings.adaptiveMasking)
}

/** Итог слияния — по тем же признакам, что и эталон, без случайных UUID. */
private fun mergeAfterDump(state: PersistedState): String {
    val ids = state.servers.map { it.id }
    val first = state.servers.firstOrNull()?.id
    return "count=${state.servers.size}" +
        " unique=${if (ids.toHashSet().size == ids.size) 1 else 0}" +
        " names=" + state.servers.joinToString(";") { it.name } +
        " selected=" + (state.selectedServerID?.let { if (it == first) "first" else "other" } ?: "-") +
        " subs=" + state.subscriptions.joinToString(";") { "${it.name}@${it.url}" } +
        " masking=${state.maskingProfile.name}" +
        " kill=${if (state.killSwitchEnabled) 1 else 0}" +
        " subref=${if (state.subscriptionAutoRefresh) 1 else 0}" +
        " learned=" + state.learnedMasking.entries.sortedBy { it.key }
            .joinToString(";") { "${it.key}=${it.value}" } +
        " split=" + (if (state.splitTunnel.enabled) "on" else "off") + ":" +
        state.splitTunnel.entries.joinToString(",")
}

/**
 * Рейтинг и учёт трафика: `ServerScoring`, `KxcFeatures` и `TrafficLedger`
 * против Swift. Числа сравниваются бит IEEE-754, а не напечатанным десятичным
 * видом: два `pow` могут разойтись в последнем бите, и это ровно то, что нужно
 * увидеть, а не спрятать допуском. Расхождения печатаются списком — как с
 * именами стран в CLDR.
 */
private fun goldenScore(dir: String?) {
    check("рейтинг и признаки kxc совпадают со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/score")
        val cases = java.io.File(folder, "histories.txt")
        val golden = java.io.File(folder, "histories.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-score.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число историй: ")
        var ulp1 = 0
        var wrong = 0
        var total = 0
        for ((index, input) in inputs.withIndex()) {
            // Тот же разбор, что у `LoaderTool score`: `Float(text)` в Foundation —
            // strtod («inf», hex-дроби), а `toFloatOrNull` на JVM «inf» не понимает,
            // и фикстура про молча потеряла бы элемент.
            val history = input.split(',').mapNotNull {
                SwiftDouble.parse(trimFoundationSpaces(it))?.toFloat()
            }
            val mine = listOf(
                ServerScoring.rankingScore(history),
                ServerScoring.averagePing(history),
                ServerScoring.stability(history),
            ) + KxcFeatures.extract(history)
            val want = expected[index].split('\t')
            expect(want.size, 5, "формат эталона «$input»: ")
            expect(want[0], input, "история эталона: ")
            val reference = (listOf(want[1], want[2], want[3]).map { it.split('=')[1] } +
                want[4].split('=', limit = 2)[1].split(' ')).map { java.lang.Long.parseUnsignedLong(it, 16) }
            expect(mine.size, reference.size, "число чисел «$input»: ")
            for ((position, value) in mine.withIndex()) {
                total += 1
                val got = java.lang.Double.doubleToRawLongBits(value)
                if (got == reference[position]) continue
                // Допуск «в один бит» прятал настоящие мутации: nextUp вокруг
                // rankingScore проходил проверку, меняя 86 чисел. После того как
                // `pow` убран из скоринга, обе стороны считают одними и теми же
                // операциями, так что расхождение любого размера — это баг.
                val distance = ulps(got, reference[position])
                if (distance == 1L) ulp1 += 1 else wrong += 1
                println("   · «$input» поле $position разошлось на $distance бит(а)")
            }
        }
        if (ulp1 + wrong > 0) {
            throw AssertionError("$ulp1 число из $total разошлись в последний бит, $wrong — сильнее; " +
                "после отказа от `pow` сверка требует точного совпадения бит")
        }


        // Имена признаков — те же строки, что Swift передаёт модели как ключи
        // словаря. Под локалью, где цифры не ASCII, Kotlin дал бы «f٠٠», и
        // модель просто не нашла бы входы.
        val names = java.io.File(folder, "names.golden.txt")
        if (!names.exists()) {
            throw AssertionError("нет ${names.name}: перегенерируй Scripts/golden-score.sh")
        }
        expect(KxcFeatures.names(), names.readLines().filter { it.isNotEmpty() }, "имена признаков: ")
    }
}

/** Разбор сценария `TrafficLedger`: те же команды, что прогоняет Swift. */
private fun goldenLedger(dir: String?) {
    check("учёт трафика совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/score")
        val scripts = java.io.File(folder, "ledger")
        val golden = java.io.File(folder, "ledger.golden.txt")
        if (!scripts.isDirectory || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-score.sh")
        }
        val files = scripts.listFiles { file -> file.name.endsWith(".txt") }?.sortedBy { it.name }
            ?: throw AssertionError("нет каталога ${scripts.absolutePath}")
        expect(files.size, golden.readLines().count { it.startsWith("=== ") }, "число сценариев: ")
        // Записи, которые Kotlin оставляет для третьего контура
        // (`verify-traffic.sh` перечитывает их настоящим Swift-декодером).
        val written = java.io.File(System.getenv("WRITTEN_TRAFFIC") ?: "/tmp/anemia-traffic-kotlin")
        written.mkdirs()
        var commands = 0
        var documents = 0
        for (script in files) {
            val name = script.name.removeSuffix(".txt")
            val ledger = TrafficLedger()
            val out = ArrayList<Pair<String, String>>()
            var wantsDocument = false
            for (line in script.readLines().filter { it.isNotEmpty() }) {
                val parts = line.split('\t')
                commands += 1
                when (parts[0]) {
                    "rec" -> {
                        val zone = java.util.TimeZone.getTimeZone(parts[7])
                        val id = if (parts[4] == "-") null else java.util.UUID.fromString(parts[4])
                        ledger.record(parts[1].toDouble(), parts[2].toLong(), parts[3].toLong(),
                                      id?.let { it to parts[5] }, parts[6].toDouble(), zone)
                    }
                    "stopped" -> ledger.stopped()
                    "reset" -> ledger.reset()
                    "forget" -> ledger.forget(parts.drop(1).map { java.util.UUID.fromString(it) }.toSet())
                    "days" -> for (day in ledger.recentDays(parts[1].toInt(), parts[2].toDouble(),
                                                            java.util.TimeZone.getTimeZone(parts[3]))) {
                        out += "day" to dayDump(day)
                    }
                    "today", "month" -> {
                        val zone = java.util.TimeZone.getTimeZone(parts[2])
                        val day = if (parts[0] == "today") ledger.today(parts[1].toDouble(), zone)
                        else ledger.month(parts[1].toDouble(), zone)
                        out += parts[0] to dayDump(day)
                    }
                    "top" -> for (total in ledger.topServers) {
                        out += "srv" to "id=${total.id.toString().uppercase()} name=${total.name}" +
                            " recv=${total.received} sent=${total.sent} total=${total.total}" +
                            " lastUsed=${bits(total.lastUsed)}"
                    }
                    "key" -> out += "key" to TrafficLedger.dayKey(parts[2].toDouble(),
                                                                 java.util.TimeZone.getTimeZone(parts[1]))
                    "dayof" -> out += "dayof" to (TrafficLedger.dateOfDay(parts[2],
                        java.util.TimeZone.getTimeZone(parts[1]))?.let { bits(it) } ?: "nil")
                    // Документ сверяется отдельно, канонически: порядок ключей у
                    // Swift случайный, а печатать числа обе стороны должны уметь
                    // одинаково — это как раз то, что проверяется.
                    "json" -> wantsDocument = true
                    else -> throw AssertionError("$name: неизвестная команда ${parts[0]}")
                }
            }
            // Порядок вывода в эталоне — тот, что давали команды; сверяем его напрямую.
            val reference = goldenLinesFor(golden, name)
            if (wantsDocument) {
                documents += 1
                val swift = reference.firstOrNull { it.startsWith("json\t") }?.removePrefix("json\t")
                    ?: throw AssertionError("$name: в эталоне нет строки json — перегенерируй golden-score.sh")
                val mine = ledger.toJson()
                expect(canonicalTraffic(Json.parse(mine)), canonicalTraffic(Json.parse(swift)),
                       "$name: документ: ")
                // Обратный ход: то, что написал Swift, Kotlin обязан прочесть и
                // переписать без потерь. Сдвиг reference date (секунды от
                // 2001-01-01, а не от эпохи Unix) виден именно здесь.
                val readBack = TrafficLedger.fromJson(swift)
                    ?: throw AssertionError("$name: Kotlin не прочитал документ Swift")
                expect(canonicalTraffic(Json.parse(readBack.toJson())),
                       canonicalTraffic(Json.parse(swift)), "$name: чтение документа Swift: ")
                java.io.File(written, "$name.json").writeText(mine, Charsets.UTF_8)
            }
            expect(out.map { "${it.first}\t${it.second}" },
                   reference.filterNot { it.startsWith("json\t") }, "$name: вывод: ")
        }
        if (documents == 0) throw AssertionError("ни одного документа не сверено — фикстуры пусты")
        println("   · сценариев: ${files.size}, команд: $commands, документов: $documents")
    }
}

/** Строки эталона одного сценария, в том порядке, в котором их напечатал Swift. */
private fun goldenLinesFor(golden: java.io.File, name: String): List<String> {
    val out = ArrayList<String>()
    var inside = false
    for (line in golden.readLines()) {
        if (line.startsWith("=== ")) {
            inside = line.removePrefix("=== ") == name
            continue
        }
        if (inside && line.isNotEmpty()) out.add(line)
    }
    return out
}

/** `LoaderTool ledger` печатает день так; порядок слов — часть контракта. */
private fun dayDump(day: TrafficLedger.Day): String =
    "id=${day.id} recv=${day.received} sent=${day.sent} time=${bits(day.time)} total=${day.total}"

/** Расстояние между двумя Double в ULP — сколько бит их делит. */
private fun ulps(a: Long, b: Long): Long {
    // Порядок вещественных чисел совпадает с порядком их битов, если знак
    // привести к монотонному: отрицательные переворачиваются.
    fun key(bits: Long): Long = if (bits >= 0) bits xor Long.MIN_VALUE else bits.inv()
    return kotlin.math.abs(key(a) - key(b))
}

/** Ровно те биты, что кладёт в Double — без разговора о формате. */
private fun bits(value: Double): String =
    java.lang.Long.toHexString(java.lang.Double.doubleToRawLongBits(value)).padStart(16, '0')

/**
 * Проверки на утечки: ответы ip.sb, Cloudflare и bash.ws разборчивы или нет, и
 * что `findings` решает про набор показаний. Сеть здесь не участвует — сверяется
 * ровно то, что обязано читаться одинаково на трёх платформах.
 */
private fun goldenLeaks(dir: String?) {
    check("ответы сервисов и вердикт утечек совпадают со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/leak")
        val cases = java.io.File(folder, "answers.txt")
        val golden = java.io.File(folder, "answers.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-leak.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число кейсов: ")
        var parsed = 0
        var refused = 0
        for ((index, input) in inputs.withIndex()) {
            val parts = input.split('\t')
            val want = expected[index]
            val got = when (parts[0]) {
                "ipsb" -> run { parsed += 1; "ipsb\t" + (runCatching { ipInfoDump(LeakCheck.parseIPSB(parts[1])) }
                    .getOrElse { refused += 1; parsed -= 1; "throw" }) }
                "trace" -> run { parsed += 1; "trace\t" + (runCatching {
                    ipInfoDump(LeakCheck.parseTrace(unescapeFixtures(parts[1])))
                }.getOrElse { refused += 1; parsed -= 1; "throw" }) }
                "bashws" -> run { parsed += 1; "bashws\t" + (runCatching {
                    LeakCheck.parseBashWS(parts[1]).joinToString(";") { dnsDump(it) }
                }.getOrElse { refused += 1; parsed -= 1; "throw" }) }
                "findings" -> {
                    val verdicts = LeakCheck.findings(
                        exit = infoField(parts[1]), direct = infoField(parts[2]),
                        ipv6 = infoField(parts[3]), dns = dnsField(parts[4]),
                    )
                    "findings\t" + (if (verdicts.isEmpty()) "чисто" else verdicts.joinToString(" ") { finding ->
                        when (finding) {
                            is LeakCheck.Finding.TunnelBypassed -> "tunnelBypassed"
                            is LeakCheck.Finding.Ipv6Leak -> "ipv6Leak(${ipInfoDump(finding.info)})"
                            is LeakCheck.Finding.DnsLeak ->
                                "dnsLeak(${finding.servers.joinToString(";") { dnsDump(it) }})"
                        }
                    })
                }
                else -> throw AssertionError("неизвестная команда ${parts[0]}")
            }
            expect(got, want, "«${parts[0]}» ${index + 1}: ")
        }
        println("   · кейсов: ${inputs.size}, разобрано ответов: $parsed, отказов: $refused")
    }
}

/** Чистая половина зонда: куда стучаться, какое SNI послать и когда сдаться. */
private fun goldenProbe(dir: String?) {
    check("политика проб совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/probe")
        val cases = java.io.File(folder, "cases.txt")
        val golden = java.io.File(folder, "cases.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-leak.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число кейсов: ")
        var rounds = 0
        var attempts = 0
        for ((index, input) in inputs.withIndex()) {
            val parts = input.split('\t')
            val got = when (parts[0]) {
                "target" -> {
                    val dial = Probing.target(parts[1], parts[2].toInt(),
                                               parts[3].takeIf { it != "-" }, parts[4] == "1")
                    "target\tusable=${if (dial.usable) 1 else 0} port=${dial.port}" +
                        " sni=${dial.serverName ?: "-"} tls=${if (dial.tls) 1 else 0}"
                }
                "collect" -> {
                    val outcomes = parts[3].split(',').map { it.toIntOrNull() }
                    val results = Probing.collect(
                        parts[1].toInt(), parts[2].takeIf { it != "-" }?.toInt(),
                    ) { attempt -> outcomes[minOf(attempt, outcomes.size - 1)] }
                    rounds += 1
                    attempts += results.size
                    "collect\t" + results.joinToString(",") { it?.toString() ?: "—" } + " всего=${results.size}"
                }
                else -> throw AssertionError("неизвестная команда ${parts[0]}")
            }
            expect(got, expected[index], "«${parts[0]}» ${index + 1}: ")
        }
        println("   · кейсов: ${inputs.size}, раундов: $rounds, попыток в них: $attempts")
    }
}

/** Те же формы, что печатает `LoaderTool leak`. */
private fun ipInfoDump(info: LeakCheck.IPInfo): String =
    "ip=${info.ip} cc=${info.countryCode ?: "-"} country=${info.country ?: "-"}" +
        " city=${info.city ?: "-"} isp=${info.isp ?: "-"}"

private fun dnsDump(server: LeakCheck.DNSServer): String =
    "ip=${server.ip} cc=${server.countryCode ?: "-"} country=${server.country ?: "-"} org=${server.org ?: "-"}"

/** `ip|cc|country|city|isp`, где `NONE` — показания вовсе не было. */
private fun infoField(text: String): LeakCheck.IPInfo? {
    if (text == "NONE") return null
    val parts = text.split('|')
    if (parts.size != 5) return null
    fun optional(value: String) = value.takeIf { it != "-" }
    // Порядок регистра сохраняется: Swift сверяет страну в верхнем регистре,
    // но наружу отдаёт то, что принёс сервис.
    return LeakCheck.IPInfo(parts[0], optional(parts[1]), optional(parts[2]),
                            optional(parts[3]), optional(parts[4]))
}

private fun dnsField(text: String): List<LeakCheck.DNSServer> {
    if (text == "-") return emptyList()
    return text.split(';').mapNotNull { item ->
        val parts = item.split('|')
        if (parts.size != 4) return@mapNotNull null
        fun optional(value: String) = value.takeIf { it != "-" }
        LeakCheck.DNSServer(parts[0], optional(parts[1]), optional(parts[2]), optional(parts[3]))
    }
}

/**
 * Две вещи, которые в бандле не видны ни в файле, ни в ссылке: «похоже ли это
 * на наш перенос» (по этому шторка решает, показывать ли предпросмотр) и перенос
 * id серверов между обновлениями подписки (от него живут выбор сервера и
 * история плагов).
 */
private fun goldenSyncHelpers(dir: String?) {
    check("узнавание бандла и перенос id совпадают со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/sync")

        val looksCases = java.io.File(folder, "looks/cases.txt")
        val looksGolden = java.io.File(folder, "looks/cases.golden.txt")
        val carryCases = java.io.File(folder, "carry/cases.txt")
        val carryGolden = java.io.File(folder, "carry/cases.golden.txt")
        if (!looksCases.exists() || !looksGolden.exists() || !carryCases.exists() || !carryGolden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-sync.sh")
        }

        val looks = looksGolden.readLines().filter { it.isNotEmpty() }
        expect(looksCases.readLines().filter { it.isNotEmpty() }.size, looks.size, "число строк looks: ")
        var recognized = 0
        for ((index, line) in looks.withIndex()) {
            val payload = line.substringBefore('\t')
            val verdict = if (SyncBundle.looksLikeBundle(payload)) "да" else "нет"
            expect(verdict, line.substringAfter('\t'), "looks ${index + 1} «$payload»: ")
            if (verdict == "да") recognized += 1
        }

        val carries = carryGolden.readLines().filter { it.isNotEmpty() }
        val carryInputs = carryCases.readLines().filter { it.isNotEmpty() }
        expect(carryInputs.size, carries.size, "число строк carry: ")
        var moved = 0
        for ((index, line) in carries.withIndex()) {
            val spec = line.substringBefore('\t')
            expect(spec, carryInputs[index], "carry ${index + 1}: ")
            val sides = spec.split('|')
            val old = sides[0].split(',').map { carriedServer(it) }
            val fresh = sides[1].split(',').map { carriedServer(it) }
            val got = SubscriptionParser.carryingIDs(old, fresh).joinToString(",") { it.id.toString() }
            expect(got, line.substringAfter('\t'), "carry «$spec»: ")
            if (old.map { it.id.toString() }.intersect(got.split(',').toSet()).isNotEmpty()) moved += 1
        }
        println("   · похоже на бандл: $recognized из ${looks.size}, переносов id: $moved наборов")
    }
}

/** Сервер для кейса переноса: identityKey вычисляется из имени, id приходит из фикстуры. */
private fun carriedServer(pair: String): ProxyServer {
    val (key, id) = pair.split('=')
    return ProxyServer(name = key, proto = ProxyProtocol.VLESS, address = key, port = 443,
                       credential = key, id = java.util.UUID.fromString(id))
}

/**
 * Конфиг отдельного движка hysteria: YAML для каждой ссылки корпуса, вместе с
 * тем, что валидатор нашёл. Текст — это то, что движок читает буквально, так что
 * сверяется он целиktом (через base64, чтобы переводы строк не спорили с форматами).
 */
private fun goldenHysteria(dir: String?) {
    check("конфиг hysteria совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/hysteria")
        val cases = java.io.File(folder, "links.txt")
        val golden = java.io.File(folder, "links.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-leak.sh")
        }
        val expected = parseBlocks(golden.readText())
        val links = cases.readLines().filter { it.isNotEmpty() }
        expect(links.size, expected.size, "число ссылок: ")
        var configs = 0
        var refused = 0
        for (line in links) {
            val key = line
            val want = expected[key] ?: throw AssertionError("нет эталона для «$key»")
            val parts = line.split('\t')
            val port = parts.getOrNull(2)?.toIntOrNull() ?: 21180
            val out = ArrayList<Pair<String, String>>()
            try {
                val server = if (parts[0] == "server") StateCodec.server(Json.parse(parts[1]))
                else ShareLinkParser.parse(parts[0])
                for (problem in HysteriaConfigBuilder.validate(server)) out.add("problem" to problem)
                val yaml = HysteriaConfigBuilder.makeClientConfig(server, port)
                out.add("yaml" to java.util.Base64.getEncoder()
                    .encodeToString(yaml.toByteArray(Charsets.UTF_8)))
                configs += 1
            } catch (error: HysteriaBuildException) {
                out.add("error" to (error.message ?: ""))
                refused += 1
            } catch (error: ProxyParseException) {
                out.add("error" to error.describe())
                refused += 1
            }
            expect(out.map { "${it.first}\t${it.second}" }, want.entries.map { "${it.key}\t${it.value}" },
                   "«$key»: ")
        }
        println("   · конфигов: $configs, отказов: $refused")
        if (configs == 0 || refused == 0) throw AssertionError("нужны и конфиги, и отказы")
    }
}

/** Проволочный формат статистики движка: байты запроса и разбор ответа. */
private fun goldenStats(dir: String?) {
    check("статистика движка совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/stats")
        val cases = java.io.File(folder, "wire.txt")
        val golden = java.io.File(folder, "wire.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-leak.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число кейсов: ")
        var requests = 0
        var parseds = 0
        var headers = 0
        var frames = 0
        var heads = 0
        for ((index, input) in inputs.withIndex()) {
            val parts = input.split('\t')
            val got = when (parts[0]) {
                "request" -> {
                    requests += 1
                    "request\t" + StatsWire.requestBytes(parts[1].toInt(),
                        parts.getOrNull(2)?.takeIf { it != "-" && it.isNotEmpty() })
                        .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
                }
                "header" -> {
                    headers += 1
                    "header\t" + StatsWire.header(parts[1], parts[2])
                        .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
                }
                "frame" -> {
                    val payload = if (parts[4] == "none") ByteArray(0) else hexBytes(parts[4])
                    frames += 1
                    "frame\t" + StatsWire.frame(parts[1].toInt(16), parts[2].toInt(16),
                        parts[3].toLong().toInt(), payload)
                        .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
                }
                "framehead" -> {
                    heads += 1
                    "framehead\t" + StatsWire.frame(parts[1].toInt(16), parts[2].toInt(16),
                        parts[3].toLong().toInt(), ByteArray(parts[4].toInt()))
                        .take(9).joinToString("") { "%02x".format(it.toInt() and 0xFF) }
                }
                "parse" -> {
                    val hex = parts.getOrNull(1) ?: ""
                    // Тот же ответ, что у инструмента: непарный хвост или не-hex
                    // символ — «bad hex», а не молчаливый разбор половину.
                    val bytes = if (hex.length % 2 != 0) null else hex.chunked(2)
                        .map { pair -> pair.toIntOrNull(16)?.takeIf { it in 0..255 }?.toByte() }
                        ?.takeIf { list -> list.all { it != null } }?.map { it!! }
                    parseds += 1
                    if (bytes == null) {
                        "parse\tbad hex"
                    } else {
                        val stats = StatsWire.parseProtobuf(bytes.toByteArray())
                        "parse\t" + (if (stats.isEmpty()) "пусто"
                        else stats.joinToString(";") { "${it.name}=${it.value}" })
                    }
                }
                else -> throw AssertionError("неизвестная команда ${parts[0]}")
            }
            expect(got, expected[index], "«${parts[0]}» ${index + 1}: ")
        }
        println("   · запросов: $requests, разборов ответа: $parseds, " +
            "HPACK-строк: $headers, кадров: $frames, шапок: $heads")
    }
}

/** Байты из hex-строки фикстуры. */
/**
 * Грамматика маскирования: движок читает `settings.noises` и `settings.fragment`
 * строго, поэтому фильтр «что отдавать движку» — это не вкус, а «примет / не
 * примет». Таблица `mask/grammar.tsv` — записи, измеренные на самом xray
 * (контур `Scripts/verify-noise-grammar.sh` перемеряет их заново); здесь
 * проверяется, что Kotlin-зеркало отвечает на них точно так же. Направление
 * сомнения важно: лишняя строка в таблице, принятая зеркалом, — это туннель,
 * который не поднимется.
 */
private fun maskGrammar(dir: String?) {
    check("фильтр маскирования совпадает с движком") {
        val file = java.io.File(dir ?: "core/src/test/resources/mask", "grammar.tsv")
        if (!file.exists()) {
            throw AssertionError("нет ${file.absolutePath}: таблицы грамматики не существует")
        }
        var rows = 0
        var accepted = 0
        var rejected = 0
        for (line in file.readLines()) {
            if (line.isEmpty() || line.startsWith("#")) continue
            val fields = line.split('\t')
            if (fields.size != 5) throw AssertionError("строка из ${fields.size} полей: «$line»")
            val (kind, a, b, c, verdict) = fields
            fun space(value: String) = value.replace("%20", " ")
            val emittable = when (kind) {
                "noise" -> AntiCensorshipOptions.Noise(space(a), space(b), space(c)).isEmittable
                "frag" -> AntiCensorshipOptions.Fragment(space(a), space(b), space(c)).isEmittable
                else -> throw AssertionError("неизвестный kind «$kind»")
            }
            val expected = when (verdict) {
                "accept" -> true
                "reject" -> false
                else -> throw AssertionError("не вердикт «$verdict» в строке «$line»")
            }
            rows += 1
            if (expected) accepted += 1 else rejected += 1
            if (emittable != expected) {
                throw AssertionError("$kind [${space(a)}] | ${space(b)} | ${space(c)}: " +
                    "зеркало — $emittable, движок — $verdict")
            }
        }
        expect(rows, 99, "строк грамматики: ")
        expect(accepted, 54, "принято движком: ")
        expect(rejected, 45, "отбраковано движком: ")
    }
}

private fun hexBytes(hex: String): ByteArray =
    hex.chunked(2).map { requireNotNull(it.toIntOrNull(16)) { "не hex: «$it»" }.toByte() }.toByteArray()

/**
 * Выученное маскирование: общий ключ сервера и ключ «на этой сети», что
 * читается при подключении и что остаётся после «забыть». Отдельно — случай,
 * где credential сам кончается на `#wifi`: его нельзя обрезать как сетевой
 * суффикс, и Swift обрезает ровно один хвост.
 */
private fun goldenMask(dir: String?) {
