        val expected = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, expected.size, "число кейсов: ")
        var keys = 0
        var lookups = 0
        for ((index, input) in inputs.withIndex()) {
            val parts = input.split('\t')
            val got = when (parts[0]) {
                "key" -> {
                    val server = StateCodec.server(Json.parse(parts[1]))
                    "key\t${server.identityKey}|${LearnedMasking.key(server, NetworkKind.of(parts[2]))}"
                }
                "serverkey" -> "serverkey\t${LearnedMasking.serverKeyOf(parts[1])}"
                "lookup" -> {
                    val server = StateCodec.server(Json.parse(parts[1]))
                    val state = StateCodec.state(parts[3])
                    lookups += 1
                    "lookup\t${LearnedMasking.profileFor(state, server, NetworkKind.of(parts[2]))?.name ?: "-"}"
                }
                "learn" -> {
                    val state = StateCodec.state(parts[3])
                    val server = StateCodec.server(Json.parse(parts[1]))
                    val profile = if (parts[2] == "?") null else MaskingProfile.of(parts[2])
                    val after = LearnedMasking.learned(state, profile, server, NetworkKind.of(parts[4]))
                    "learn\t" + after.learnedMasking.entries.sortedBy { it.key }
                        .joinToString(";") { "${it.key}=${it.value}" }
                }
                else -> throw AssertionError("неизвестная команда ${parts[0]}")
            }
            if (parts[0] == "key") keys += 1
            expect(got, expected[index], "«${parts[0]}» ${index + 1}: ")
        }
        println("   · кейсов: ${inputs.size}, ключей: $keys, чтений: $lookups")
    }
}

private var passed = 0
private var failed = 0

private fun check(name: String, body: () -> Unit) {
    try {
        body()
        passed += 1
        println("✔ $name")
    } catch (error: Throwable) {
        failed += 1
        println("✘ $name — ${error.message}")
    }
}

private fun <T> expect(actual: T, expected: T, what: String = "") {
    if (actual != expected) {
        throw AssertionError("$what ожидалось=$expected получено=$actual")
    }
}

private fun expectTrue(condition: Boolean, what: String) {
    if (!condition) throw AssertionError(what)
}

private fun expectThrows(what: String, body: () -> Unit) {
    val threw = try {
        body(); false
    } catch (error: AwgConfigException) {
        true
    }
    if (!threw) throw AssertionError("ожидалось исключение: $what")
}

/** Байты UTF-16LE без собственного BOM — так Foundation пишет такой документ. */
private fun String.encodeUtf16LE(): ByteArray {
    val out = java.io.ByteArrayOutputStream()
    for (char in this) {
        out.write(char.code and 0xFF)
        out.write((char.code shr 8) and 0xFF)
    }
    return out.toByteArray()
}


