/**
 * Решение «пора ли перезапрашивать панель без пользователя» — `sub/due.txt`
 * это те же кейсы, что проглотил `LoaderTool subdue`, и золотой ответ Swift
 * лежит рядом. Сверяется и зажатый интервал, и вердикт: возраст сам по себе
 * не поймает мутированный clamp, а зажатый интервал сам по себе не поймает
 * мутнувший TLS-гейт.
 */
private fun goldenSubscriptionDue(dir: String?) {
    check("вердикт автообновления совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/sub")
        val cases = java.io.File(folder, "due.txt")
        val golden = java.io.File(folder, "due.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Scripts/golden-sub.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val rows = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, rows.size, "число кейсов: ")
        /** `Int(maxAge)` на Swift ловит trap по NaN/∞ — печатаем как `LoaderTool`. */
        fun ageText(value: Double) = when {
            value.isNaN() -> "nan"
            value == Double.POSITIVE_INFINITY -> "inf"
            value == Double.NEGATIVE_INFINITY -> "-inf"
            else -> value.toInt().toString()
        }
        var verdicts = 0
        for ((index, row) in rows.withIndex()) {
            val line = inputs[index]
            val parts = line.split('\t')
            val label = parts.firstOrNull() ?: ""
            // Пустой ярлык — не «пропустить кейс», а отдельный отказ: молча
            // выброшенная строка это ровно та дыра, из-за которой золотые
            // сверки когда-то сравнивали пустоту.
            if (label.isEmpty()) {
                expect("error\tno label\t$line", row, "кейс без ярлыка: ")
                continue
            }
            // `readLines()` на JVM режет строку по CR, Swift — нет.
            if (line.contains('\r')) {
                expect("$label\terror\tcr", row, "кейс с CR: ")
                continue
            }
            if (parts.size != 7) {
                expect("$label\terror\tcolumns ${parts.size}", row, "числе колонок: ")
                continue
            }
            val url = parts[1]
            if (url.isEmpty()) {
                expect("$label\terror\tno url", row, "кейс без url: ")
                continue
            }
            if (parts[6] != "" && parts[6] != "0" && parts[6] != "1") {
                expect("$label\terror\tallowInsecure", row, "кейс с чужим флагом: ")
                continue
            }
            // Поля разбираются в том же порядке, что у `LoaderTool subdue`, и
            // первым падает то, которое кривое: «кейс не разобран» должно
            // называть себя, а не превращаться в молчаливое «нет истории».
            var problem: String? = null
            fun number(name: String, column: Int): Double? {
                val raw = parts[column]
                if (raw.isEmpty()) return null
                val value = SwiftDouble.parse(raw)
                if (value == null) {
                    if (problem == null) problem = name
                    return null
                }
                return value
            }
            val fetched = number("lastUpdated", 2)
            val now = number("now", 3)
            val interval = number("panelInterval", 4)
            val defaultAge = number("defaultAge", 5)
            val broken = problem ?: if (now == null) "now" else null
            if (broken != null) {
                expect("$label\terror\t$broken", row, "кейс с кривым полем: ")
                continue
            }
            val sub = Subscription(
                name = label,
                url = url,
                lastUpdated = fetched?.minus(Subscription.REFERENCE_DATE_SECONDS),
            )
            val press = parts[6] == "1"
            // Пустой столбец дефолта отдаёт дефолт функции — тот же смысл, что
            // в `LoaderTool subdue`: правка константы обязана покраснеть здесь.
            val (maxAge, due) = if (defaultAge == null) {
                sub.refreshMaxAge(interval) to sub.refreshIsDue(now!!, interval, allowInsecure = press)
            } else {
                sub.refreshMaxAge(interval, defaultAge) to
                    sub.refreshIsDue(now!!, interval, defaultAge, press)
            }
            expect("$label\tmaxAge=${ageText(maxAge)}\tdue=${if (due) 1 else 0}", row, "«$label»: ")
            verdicts += 1
        }
        // Пол, а не только «все строки сошлись»: фикстура, целиком развалившаяся
        // в `error`, даёт зелёную проверку, которая ничего не сверяет.
        expectTrue(verdicts >= 25, "вердиктов всего $verdicts — кейсы развалились в отказы")
        println("   · кейсов: ${inputs.size}, вердиктов: $verdicts")
    }
}

