/**
 * Расписание проверок здоровья — `health/run.txt` прогнан через `LoaderTool
 * healthdue` на Swift. Печатается и `due`, и `fresh`: без второго «проверка не
 * идёт» и «данных нет» печатались бы одной строкой, а решение о переключении
 * различает именно их.
 */
private fun goldenHealthRun(dir: String?) {
    check("расписание проверок здоровья совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/health")
        val cases = java.io.File(folder, "run.txt")
        val golden = java.io.File(folder, "run.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Android/Scripts/golden-health.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val rows = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, rows.size, "число кейсов: ")
        var verdicts = 0
        for ((index, row) in rows.withIndex()) {
            val line = inputs[index]
            val parts = line.split('\t')
            val label = parts.firstOrNull() ?: ""
            if (label.isEmpty()) {
                expect("error\tno label\t$line", row, "кейс без ярлыка: ")
                continue
            }
            if (line.contains('\r')) {
                expect("$label\terror\tcr", row, "кейс с CR: ")
                continue
            }
            if (parts.size != 8) {
                expect("$label\terror\tcolumns ${parts.size}", row, "числе колонок: ")
                continue
            }
            var problem: String? = null
            // Числа — грамматикой Foundation: `Double("0x10")` в Swift это 16,
            // `toDoubleOrNull` на JVM — null, и одна фикстура прочиталась бы на
            // двух сторонах по-разному. `inf`/`nan` отказывают обеим сторонам.
            fun age(name: String, column: Int): Double? {
                val raw = parts[column]
                if (raw.isEmpty()) return null
                val value = SwiftDouble.parse(raw)
                if (value == null || !value.isFinite()) {
                    if (problem == null) problem = name
                    return null
                }
                return value
            }
            val watched = age("watchedAge", 1)
            val wanted = age("wantedAge", 2)
            val checked = age("checkedAge", 3)
            val watchWindow = age("watchedWindow", 4)
            val wantWindow = age("wantedWindow", 5)
            val every = age("interval", 6)
            val stale = age("staleAfter", 7)
            if (problem != null) {
                expect("$label\terror\t$problem", row, "кейс с кривым полем: ")
                continue
            }
            val schedule = HealthSchedule().apply {
                watchWindow?.let { watchedWindow = it }
                wantWindow?.let { wantedWindow = it }
                every?.let { interval = it }
                stale?.let { staleAfter = it }
            }
            val due = schedule.healthDue(watched, wanted, checked)
            val fresh = schedule.signalFresh(checked)
            expect("$label\tdue=${if (due) 1 else 0}\tfresh=${if (fresh) 1 else 0}", row, "«$label»: ")
            verdicts += 1
        }
        expectTrue(verdicts >= 20, "вердиктов всего $verdicts — кейсы развалились в отказы")
        println("   · кейсов: ${inputs.size}, вердиктов: $verdicts")
    }
}

