                continue
            }
            if (parts.size != 5) {
                expect("$label\terror\tcolumns ${parts.size}", row, "числе колонок: ")
                continue
            }
            var problem: String? = null
            val ops = listOf("note", "refund", "prune", "ages")
            val op = parts[1]
            if (op !in ops && problem == null) problem = "op"
            fun real(name: String, text: String): Double? {
                val value = SwiftDouble.parse(text)
                if (value == null || !value.isFinite()) {
                    if (problem == null) problem = name
                    return null
                }
                return value
            }
            val now = real("now", parts[2])
            val window = real("window", parts[3])
            val marks = if (parts[4].isEmpty()) emptyList() else parts[4].split(',').map {
                real("marks", it) ?: 0.0
            }
            if (problem != null) {
                expect("$label\terror\t$problem", row, "кейс с кривым полем: ")
                continue
            }
            val budget = SwitchBudget(window ?: (15 * 60.0), marks)
            when (op) {
                "note" -> budget.note(now!!)
                "refund" -> budget.refund(now!!)
                "prune" -> budget.prune(now!!)
            }
            // Печатается как Swift `String(TimeInterval)`: «999.0», а не «999» —
            // фикстура специально целочисленная, дробные Double Foundation и JVM
            // печатают по-разному, и сверять их побайтно нельзя.
            fun list(values: List<Double>) =
                if (values.isEmpty()) "-" else values.joinToString(",") { it.toString() }
            expect(
                "$label\top=$op\tmarks=${list(budget.marks)}\tages=${list(budget.ages(now!!))}",
                row, "«$label»: ",
            )
            verdicts += 1
        }
        expectTrue(verdicts >= 15, "вердиктов всего $verdicts — кейсы развалились в отказы")
        println("   · кейсов: ${inputs.size}, вердиктов: $verdicts")
    }
}

/**
 * Вердикт переключения — `switch/due.txt` это те же кейсы, что проглотил
 * `LoaderTool switchdue`, а ответ Swift лежит рядом в золотом. Разбирается
 * строка здесь по тем же правилам, что в инструменте: кривое поле обязано
 * называть себя и на Kotlin-стороне, иначе обрезанная фикстура читаётся как
 * «переключений не было».
 */
/**
 * Правила здоровья туннеля — `health/cases.txt` прогнан через `LoaderTool
 * health` на Swift, ответ лежит рядом. сверяется и вердикт, и счётчик подряд:
 * без него «сброс после ответа» неотличим от «накопления», а именно на этом
 * держится порог «два подряд» в решении о переключении.
 */
private fun goldenHealth(dir: String?) {
    check("правила здоровья туннеля совпадают со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/health")
        val cases = java.io.File(folder, "cases.txt")
        val golden = java.io.File(folder, "cases.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Android/Scripts/golden-health.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val rows = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, rows.size, "число кейсов: ")
        var verdicts = 0
        for ((index, row) in rows.withIndex()) {
            val line = inputs[index]
            val parts = line.split('\t')
            val label = parts.firstOrNull() ?: ""
            if (label.isEmpty()) {
                expect("error\tno label\t$line", row, "кейс без ярлыка: ")
                continue
            }
            if (line.contains('\r')) {
                expect("$label\terror\tcr", row, "кейс с CR: ")
                continue
            }
            if (parts.size != 12) {
                expect("$label\terror\tcolumns ${parts.size}", row, "числе колонок: ")
                continue
            }
            var problem: String? = null
            // `Int32(text)` в Swift и `toIntOrNull()` на JVM — одно множество
            // значений; 64-битный `Int` Swift прочитал бы то, чего JVM не видит.
            fun int(name: String, column: Int): Int? {
                val raw = parts[column]
                if (raw.isEmpty()) return null
                val value = raw.toIntOrNull()
                if (value == null && problem == null) problem = name
                return value
            }
            val mode = parts[1]
            if (mode != "xray" && mode != "awg" && problem == null) problem = "mode"
            val ms = int("ms", 2)
            val prevUp = int("prevUp", 3)
            val prevDown = int("prevDown", 4)
            if ((prevUp == null) != (prevDown == null) && problem == null) problem = "prev pair"
            val curUp = int("curUp", 5)
            val curDown = int("curDown", 6)
            if ((curUp == null) != (curDown == null) && problem == null) problem = "counters pair"
            val latency = int("latency", 7)
            val limit = int("limit", 8)
            val floor = int("sendFloor", 9)
            val start = int("startFailures", 10)
            if (start == null && problem == null) problem = "startFailures"
            val startHealth = int("startHealth", 11)
            if (problem != null) {
                expect("$label\terror\t$problem", row, "кейс с кривым полем: ")
                continue
            }
            // Пустой столбец порога оставляет дефолт самой политики — ровно как
            // в `LoaderTool health`: иначе харнесс подставлял бы константу сам.
            val rules = TunnelHealth().apply {
                limit?.let { requestLimitMs = it }
                floor?.let { sendFloorBytes = it.toLong() }
            }
            val outcome = if (mode == "xray") {
                rules.request(ms)
            } else {
                val counters = if (curUp != null && curDown != null) TrafficCounters(curUp.toLong(), curDown.toLong()) else null
                val previous = if (prevUp != null && prevDown != null) TrafficCounters(prevUp.toLong(), prevDown.toLong()) else null
                rules.counters(counters, previous, latency)
            }
            val state = rules.apply(outcome, HealthState(startHealth, start!!))
            val printed = StringBuilder("$label\tstart=$start\tfrom=${startHealth ?: "nil"}")
            when (outcome) {
                HealthOutcome.Silence -> printed.append("\toutcome=silence")
                is HealthOutcome.Measured -> printed
                    .append("\toutcome=measured\tms=${outcome.ms}\tfailed=${if (outcome.failed) 1 else 0}")
            }
            printed.append("\thealth=${state.health ?: "nil"}\tfailures=${state.failures}")
            expect(printed.toString(), row, "«$label»: ")
            verdicts += 1
        }
        expectTrue(verdicts >= 20, "вердиктов всего $verdicts — кейсы развалились в отказы")
        println("   · кейсов: ${inputs.size}, вердиктов: $verdicts")
    }
}

private fun goldenSwitchDue(dir: String?) {
    check("вердикт переключения совпадает со Swift") {
        val folder = java.io.File(dir ?: "core/src/test/resources/switch")
        val cases = java.io.File(folder, "due.txt")
        val golden = java.io.File(folder, "due.golden.txt")
        if (!cases.exists() || !golden.exists()) {
            throw AssertionError("нет фикстур в ${folder.absolutePath}: перегенерируй Android/Scripts/golden-switch.sh")
        }
        val inputs = cases.readLines().filter { it.isNotEmpty() }
        val rows = golden.readLines().filter { it.isNotEmpty() }
        expect(inputs.size, rows.size, "число кейсов: ")
        var verdicts = 0
        for ((index, row) in rows.withIndex()) {
            val line = inputs[index]
            val parts = line.split('\t')
            val label = parts.firstOrNull() ?: ""
            if (label.isEmpty()) {
                expect("error\tno label\t$line", row, "кейс без ярлыка: ")
                continue
            }
            if (line.contains('\r')) {
                expect("$label\terror\tcr", row, "кейс с CR: ")
                continue
            }
            if (parts.size != 8) {
                expect("$label\terror\tcolumns ${parts.size}", row, "числе колонок: ")
                continue
            }
            var problem: String? = null
            fun flag(name: String, column: Int): Boolean {
                return when (parts[column]) {
                    "0" -> false
                    "1" -> true
                    else -> {
                        if (problem == null) problem = name
                        false
                    }
                }
            }
            // `Int32(text)` в Swift и `toIntOrNull()` на JVM — одно и то же
            // множество значений; `Int` Swift вмещает вдвое больше, и число
            // между ними одна сторона прочитала бы, а вторая — нет.
            fun narrow(name: String, column: Int): Int? {
                val value = parts[column].toIntOrNull()
                if (value == null && problem == null) problem = name
                return value
            }
            // Числа — через грамматику Foundation: `Double("nan")` в Swift это
            // число, а `toDoubleOrNull()` на JVM — null, и отказ обязан выйти
            // одинаковый.
            fun real(name: String, column: Int): Double? {
                val value = SwiftDouble.parse(parts[column])
                if (value == null || !value.isFinite()) {
                    if (problem == null) problem = name
                    return null
                }
                return value
            }
            val enabled = flag("enabled", 1)
            val connected = flag("connected", 2)
            val busy = flag("busy", 3)
            val serverCount = narrow("serverCount", 4)
            val failures = if (parts[5].isEmpty()) null else narrow("healthFailures", 5)
            val sessionAge = real("sessionAge", 6)
            val ages = if (parts[7].isEmpty()) emptyList() else parts[7].split(',').map { token ->
                val value = SwiftDouble.parse(token)
                if (value == null || !value.isFinite()) {
                    if (problem == null) problem = "recentSwitches"
                    0.0
                } else {
                    value
                }
            }
            if (problem != null) {
                expect("$label\terror\t$problem", row, "кейс с кривым полем: ")
                continue
            }
            val policy = AutoSwitchPolicy()
            val verdict = policy.decide(
                enabled = enabled,
                connected = connected,
                busy = busy,
                serverCount = serverCount ?: 0,
                healthFailures = failures,
                sessionAge = sessionAge ?: 0.0,
                recentSwitches = ages,
            )
            expect(
                "$label\tkept=${policy.retained(ages).size}\tverdict=${verdict.label}", row, "«$label»: ",
            )
            verdicts += 1
        }
        expectTrue(verdicts >= 25, "вердиктов всего $verdicts — кейсы развалились в отказы")
        println("   · кейсов: ${inputs.size}, вердиктов: $verdicts")
    }
}

