        expect(Formatting.speed(8_200_000.0), "8,2 Мбит/с", "ниже 9,95 — с дробью")
        expect(Formatting.speed(4_820_000.0), "4,8 Мбит/с", "4,82")
        expect(Formatting.speed(999_500.0), "1,0 Мбит/с", "ступенька на 999,5")
        expect(Formatting.speed(999_499.0), "999 Кбит/с", "ступенька ещё нет")
        expect(Formatting.speed(0.0), "0 Кбит/с", "ноль")
        expect(Formatting.speed(-5.0), "0 Кбит/с", "отрицательная скорость")
        expect(Formatting.speedCompact(48_200_000.0), "48М", "для уголка острова")
        expect(Formatting.bytes(1_240_000_000), "1,2 ГБ", "гигабайты")
        expect(Formatting.bytes(86_000_000), "86 МБ", "мегабайты без дробей")
        expect(Formatting.bytes(999), "999 Б", "байты")
        // Верх ступени лестницы: Swift печатает разряды с NBSP (замерено по
        // тому же коду ActivityText/Bytes), поэтому группировку включать нельзя.
        expect(Formatting.speed(1_040_000_000_000.0), "1\u00A0040 Гбит/с", "скорость через гигабит")
        expect(Formatting.speedCompact(12_345_000_000_000.0), "12\u00A0345Г", "компактно с разрядом")
        expect(Formatting.bytes(999_500_000_000_000), "1\u00A0000 ТБ", "ступенька на 999,5 ТБ")
        expect(Formatting.bytes(1_040_000_000_000_000), "1\u00A0040 ТБ", "байты через терабайт")
        expect(Formatting.sessionLength(35.0), "35 с", "секунды")
        expect(Formatting.sessionLength(240.0), "4 мин", "минуты")
        expect(Formatting.sessionLength(4324.0), "1 ч 12 мин", "часы и минуты")
        expect(Formatting.sessionLength(7200.0), "2 ч", "ровно часы")
        expect(Formatting.clock(4324.0), "1:12", "часы:минуты")
    }

    println()
    println(if (failed == 0) "✓ пройдено проверок: $passed"
    else "✗ провалено $failed из ${passed + failed}")
    if (failed > 0) kotlin.system.exitProcess(1)
}


/**
 * Файловый слой состояния. `StatePersistence` — это не только разбор, но и
 * страховка, prune и атомарная запись, и эталона из Swift для него нет
 * (`FileManager` и `JSONEncoder` живут по эту сторону), поэтому проверяются
 * свойства, которые можно наблюдать на настоящем каталоге: имя страховки,
 * её содержимое, сколько их остаётся, и что бывает на нечитаемом файле.
 */
private fun stateFileLayer() {
    check("файл состояния: страховка, prune и атомарная запись") {
        val directory = java.nio.file.Files.createTempDirectory("anemia-state").toFile()
        val store = java.io.File(directory, "state.json")
        val stamp = 1_700_000_000_000L
        val persistence = StatePersistence(store) { stamp }
        fun backups(): List<String> = (directory.list { _, name -> name.endsWith(".bak") } ?: emptyArray()).sorted()

        // Нет файла — не испорченный магазин: жаловаться и страховаться не на что.
        val absent = persistence.load()
        expect(absent.decoded, true, "отсутствующий файл — не порча: ")
        expect(absent.state, PersistedState(), "пустое состояние: ")
        expect(backups(), emptyList(), "страховок быть не должно: ")

        val server = ProxyServer(
            name = "Нидерланды", proto = ProxyProtocol.VLESS, address = "example.com",
            port = 443, credential = "b831381d-6324-4d53-ad4f-8cda48b30811",
        )
        persistence.save(PersistedState(servers = listOf(server)))
        expect(backups(), emptyList(), "после удачной записи страховок нет: ")
        expect(
            (directory.list() ?: emptyArray()).filter { it.startsWith("state.json") }.sorted(),
            listOf("state.json"), "временных файлов не осталось: ",
        )
        val again = StatePersistence(store).load()
        expect(again.state.servers.map { it.name }, listOf("Нидерланды"), "сервер дожил: ")
        expect(again.state.servers.first().id, server.id, "id не переставился: ")

        // Мусор вместо JSON: страховка с исходными байтами и именем как у Swift.
        val broken = "{not json at all"
        store.writeText(broken)
        expect(persistence.load().decoded, false, "мусор не размечтовался: ")
        expect(backups(), listOf("state.json.corrupt-$stamp.bak"), "имя страховки: ")
        expect(
            java.io.File(directory, "state.json.corrupt-$stamp.bak").readText(), broken,
            "страховка хранит исходные байты: ",
        )

        // Частичная потеря — тоже повод: один битый элемент из двух.
        backups().forEach { java.io.File(directory, it).delete() }
        store.writeText("""{"servers":[${StateCodec.encode(server)},"мусор"]}""")
        val partial = persistence.load()
        expect(partial.state.servers.size, 1, "здоровый элемент пережил: ")
        expect(partial.needsBackup, true, "а потерю видно: ")

        // Пять порченых запусков — остаются три самых свежих.
        backups().forEach { java.io.File(directory, it).delete() }
        store.writeText("{")
        for (second in 0..4) StatePersistence(store) { stamp + second }.load()
        expect(
            backups(), (2..4).map { "state.json.corrupt-${stamp + it}.bak" },
            "prune оставляет три свежих: ",
        )

        // Чужие файлы не трогает. Временный осколок тоже: читающий не знает,
        // чья запись не завершилась, а уборка на `load()` съедает чужой ещё не
        // записанный файл — два процесса одного приложения (интерфейс и `:vpn`)
        // пересекаются здесь постоянно.
        java.io.File(directory, "other.json.corrupt-9.bak").writeText("не наше")
        java.io.File(directory, "state.json.999.tmp").writeText("остаток ключей")
        store.writeText("{")
        persistence.load()
        expectTrue(java.io.File(directory, "other.json.corrupt-9.bak").exists(), "чужая страховка цела: ")
        expectTrue(java.io.File(directory, "state.json.999.tmp").exists(), "чужой осколок не тронут: ")

        // Два писателя в одну миллисекунду: имя временного файла уникально,
        // поэтому обе записи доходят целиком (с общим именем на метке по
        // секундам они столкнулись бы в одном файле).
        val frozen = StatePersistence(store) { stamp }
        val second = server.copy(name = "Финляндия")
        Thread { frozen.save(PersistedState(servers = listOf(server))) }.apply { start() }.join()
        Thread { frozen.save(PersistedState(servers = listOf(second))) }.apply { start() }.join()
        expect(
            StatePersistence(store).load().state.servers.map { it.name }, listOf("Финляндия"),
            "последняя запись полная: ",
        )
        // The Android/Linux behavior depends on POSIX rename and file permissions.
        // Windows cannot replace an open file through java.nio ATOMIC_MOVE.
        if ("posix" in java.nio.file.FileSystems.getDefault().supportedFileAttributeViews()) {
            // Настоящая гонка: имя временного файла должно быть уникальным, а не
            // выводиться из часов. Иначе читатель ловит полфайла — на старом
            // варианте (`<имя>.tmp-<мс>`) это 92 пустых и 8 обрезанных чтения.
            val torn = java.util.concurrent.atomic.AtomicInteger()
            val racing = java.util.concurrent.atomic.AtomicBoolean(true)
            val readers = List(2) {
                Thread {
                    while (racing.get()) {
                        val text = runCatching { store.readText() }.getOrDefault("")
                        if (!text.startsWith("{") || !text.endsWith("}")) torn.incrementAndGet()
                    }
                }.apply { start() }
            }
            val writers = List(2) {
                Thread {
                    repeat(200) { frozen.save(PersistedState(servers = listOf(if (it % 2 == 0) server else second))) }
                }.apply { start() }
            }
            writers.forEach { it.join() }
            racing.set(false)
            readers.forEach { it.join() }
            expect(torn.get(), 0, "ни одной оборванной записи в гонке: ")
            // Единственный .tmp в каталоге — тот самый чужой осколок, который мы
            // намеренно оставили в покое: наши записи не после себя ничего не несут.
            expect(
                (directory.list { _, name -> name.endsWith(".tmp") } ?: emptyArray()).sorted().toList(),
                listOf("state.json.999.tmp"), "своих осколков не осталось: ",
            )

            // Права 0600, а не 0644 по умолчанию: в файле приватные ключи.
            expect(
                java.nio.file.Files.getPosixFilePermissions(store.toPath()).map { it.name }.sorted(),
                listOf("OWNER_READ", "OWNER_WRITE"), "права файла состояния: ",
            )
        }

        // Метка — миллисекунды: два повреждения в одну секунду затёрли бы друг
        // друга, а с фиксированными часами это не проверить.
        val stamped = StatePersistence(store)
        backups().forEach { java.io.File(directory, it).delete() }
        store.writeText("{")
        stamped.load()
        val digits = backups().maxOfOrNull { name ->
            Regex("corrupt-(\\d+)\\.bak").find(name)?.groupValues?.get(1)?.length ?: 0
        }
        expect(digits, 13, "метка страховки в миллисекундах: ")

        // Каталог с именем страховки не съедает место в «трёх лучших».
        backups().forEach { java.io.File(directory, it).delete() }
        java.io.File(directory, "state.json.corrupt-9999999999999.bak").mkdirs()
        for (extra in 0..3) {
            store.writeText("{")
            StatePersistence(store) { stamp + extra }.load()
        }
        expect(
            backups().count { java.io.File(directory, it).isFile }, 3,
            "каталог-притворщик не занял слот: ",
        )
        java.io.File(directory, "state.json.corrupt-9999999999999.bak").deleteRecursively()

        // Документ в UTF-16 с BOM Foundation читает, а `String(raw, UTF_8)` —
        // нет: без разбора кодировки это «магазин испорчен», страховка и пустой
        // список серверов вместо ровно того же состояния.
        val utf16 = java.io.File(directory, "utf16.json")
        val body = byteArrayOf(0xFF.toByte(), 0xFE.toByte())
        utf16.writeBytes(body + "{\"servers\":[]}".encodeUtf16LE())
        val wide = StatePersistence(utf16).load()
        expect(wide.decoded, true, "UTF-16 состояние читается: ")
        expect(wide.needsBackup, false, "и не считается порчей: ")

        // Нечитаемый файл — «состояния нет», и никакого страхования (иначе
        // временный сбой прав превратился бы в перезапись пустотой).
        backups().forEach { java.io.File(directory, it).delete() }
        store.writeText(broken)
        store.setReadable(false)
        try {
            if (!store.canRead()) {
                val denied = persistence.load()
                expect(denied.state, PersistedState(), "нечитаемый файл читается как пустой: ")
                expect(denied.decoded, true, "и не считается порчей: ")
                expect(backups(), emptyList(), "и не порождает страховку: ")
            }
        } finally {
            store.setReadable(true)
        }

        // Каталог вместо файла: читается как пустой, пишется с ошибкой и не
        // сносит сам себя.
        val asDirectory = java.io.File(directory, "dir.json")
        asDirectory.mkdirs()
        val dirStore = StatePersistence(asDirectory)
        expect(dirStore.load().state, PersistedState(), "каталог вместо файла: ")
        val threw = try {
            dirStore.save(PersistedState()); false
        } catch (error: Exception) {
            true
        }
        expectTrue(threw, "запись в каталог обязана бросить: ")
        expectTrue(asDirectory.isDirectory, "каталог на месте: ")
    }
}

/**
 * Адреса туннельного интерфейса, которые профиль выдал этому peer. сверяется
 * правилом, а не эталоном: разбор `Address` живёт в расширении iOS
 * (`TunnelPlan.amneziaWG`), до которого `LoaderTool` не дотягивается.
 */
private fun awgInterfaceAddresses() {
    check("адреса туннельного интерфейса из профиля") {
        val cases = listOf(
            "10.8.0.5/24" to listOf("10.8.0.5/24"),
            "10.8.0.5" to listOf("10.8.0.5/32"),
            // без префикса — полная длина адреса, и для IPv6 это 128, а не 32
            "fdfd::1" to listOf("fdfd::1/128"),
            // IPv4 первыми, каким бы ни был порядок в профиле
            "fdfd:1234::1/64, 10.8.0.5/24" to listOf("10.8.0.5/24", "fdfd:1234::1/64"),
            // два адреса одной семьи — оба: сервер принимает пакеты только с выданных
            "10.8.0.5/24, 10.9.0.1/32" to listOf("10.8.0.5/24", "10.9.0.1/32"),
            // loopback, выданный сервером, остаётся: туннель ставит то, что выдали
            "127.0.0.1/32" to listOf("127.0.0.1/32"),
            "10.8.0.5/33" to emptyList(),
            "10.8.0.5/" to emptyList(),
            "мусор/8" to emptyList(),
            "10.8.0.5/24 , fdfd::1/8" to listOf("10.8.0.5/24", "fdfd::1/8"),
            "" to emptyList(),
        )
        for ((raw, want) in cases) {
            val got = AmneziaWg.tunnelInterfaceAddresses(raw).map { "${it.address}/${it.prefix}" }
            expect(got, want, "«$raw»: ")
        }
        expect(AmneziaWg.tunnelInterfaceAddresses(null), emptyList(), "ключа нет: ")
    }

    /**
     * То же правило, что на macOS и iOS: `DNS =` у wg-quick смешанная — имена
     * в ней законны (уходят в `search`), а `VpnService.Builder.addDnsServer`
     * принимает только числовой адрес. Без отсечения одно имя в профиле
     * обрывало подъём туннеля целиком.
     */
    check("резолверы из профиля: только адреса") {
        val mixed = WireGuardProfile(
            peerPublicKey = "k",
            dns = listOf("resolver.lan", "10.8.1.1", "2606:4700:4700::1111"),
        )
        expect(mixed.dns.size, 3, "исходный список трогать нельзя: ")
        expect(mixed.resolverAddresses, listOf("10.8.1.1", "2606:4700:4700::1111"), "имена вперемешку: ")
        val onlyNames = WireGuardProfile(peerPublicKey = "k", dns = listOf("dns.google"))
        expect(onlyNames.resolverAddresses, emptyList(), "одних имён: ")
        expect(WireGuardProfile(peerPublicKey = "k").resolverAddresses, emptyList(), "пустого профиля: ")
    }
}
